    let given = [ V3A, 0x7fffffff80000000UL; V3B, 0xffffffff00000001UL ]
    let wanted = [ V1A, 0x0000000007080808UL; V1B, 0x0000000008080800UL ]
    oracle only64 "103c1e02" given wanted

