    let wanted =
      [ CR6_0, 0UL
        CR6_1, 1UL
        CR6_2, 0UL
        CR6_3, 0UL
        V1A, 0x0000000000000000UL
        V1B, 0x000000987654321fUL ]
    oracle only64 "10221b41" given wanted

