      [ R6, 0xfffffffffffffUL
        R7, 0xfffffffffffff800UL
        F1, 0xbad0bad0bad0badUL
        VSRL1, 0xbad0bad0bad0badUL ]
      []
      [ F1, 0xfffffffffffffUL; VSRL1, 0x0UL ]
