  /// <summary>
  /// divdo sets XER[OV] where the quotient cannot be represented in 64 bits
  /// -- the most negative doubleword over -1, a zero divisor -- and clears it
  /// where it can, ORs it into XER[SO] and leaves XER[CA] alone. The
  /// quotients the ISA leaves undefined are not checked. Values from
  /// qemu-ppc64 -cpu power10.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC64] DIVDO records an overflow in OV``() =
    let max, min = 0x7fffffffffffffffUL, 0x8000000000000000UL
    let fives, tens = 0x5555555555555555UL, 0xaaaaaaaaaaaaaaaaUL
    (* divdo r5, r6, r7 *)
    expectR5 ppc64s "7ca63fd2" [ max, 1UL, max; fives, tens, 0UL ]
    expectStatus
      "7ca63fd2"
      [ max, 1UL, 0xe00c0000UL, so ||| ca
        min, UInt64.MaxValue, 0x20040000UL, so ||| ov ||| ca
        0x1234UL, 0UL, 0UL, so ||| ov
        fives, tens, 0x40080000UL, 0UL ]

  /// <summary>
  /// divduo sets XER[OV] for a zero divisor and clears it where the quotient
  /// fits, ORs it into XER[SO] and leaves XER[CA] alone. Values from
  /// qemu-ppc64 -cpu power10.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC64] DIVDUO records an overflow in OV``() =
    let max = 0x7fffffffffffffffUL
    (* divduo r5, r6, r7 *)
    expectR5 ppc64s "7ca63f92" [ max, 1UL, max ]
    expectStatus
      "7ca63f92"
      [ max, 1UL, 0xe00c0000UL, so ||| ca
        0x1234UL, 0UL, 0x20040000UL, so ||| ov ||| ca ]

  /// <summary>
  /// mulldo sets XER[OV] where the product is past the signed doubleword
  /// range and clears it where it is not, ORs it into XER[SO] and leaves
  /// XER[CA] alone; the low doubleword of the product is the result either
  /// way. Values from qemu-ppc64 -cpu power10.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC64] MULLDO records an overflow in OV``() =
    let max, min = 0x7fffffffffffffffUL, 0x8000000000000000UL
    let a, b = 0x123456789abcdefUL, 0xfedcba9876543210UL
    (* mulldo r5, r6, r7 *)
    expectR5
      ppc64s
      "7ca63dd2"
      [ min, UInt64.MaxValue, min
        a, b, 0x2236d88fe5618cf0UL ]
    expectStatus
      "7ca63dd2"
      [ min, UInt64.MaxValue, 0x20040000UL, so ||| ov ||| ca
        a, b, 0UL, so ||| ov
        max, 1UL, 0xe00c0000UL, so ||| ca ]

  /// <summary>
  /// divdo. sets CR0 from the quotient and copies XER[SO] into it after OV
  /// has been ORed in, so an overflow shows in CR0[SO] even when XER[SO]
  /// started clear; the rest of CR0 is then undefined. Values from
  /// qemu-ppc64 -cpu power10.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC64] DIVDO. records in CR0``() =
    let max = 0x7fffffffffffffffUL
    let fives, tens = 0x5555555555555555UL, 0xaaaaaaaaaaaaaaaaUL
    (* divdo. r5, r6, r7 *)
    expectCR0
      "7ca63fd3"
      [ max, 1UL, 0xe00c0000UL, 0xfUL, 0b0101UL
        fives, tens, 0x40080000UL, 0xfUL, 0b0010UL
        0x1234UL, 0UL, 0UL, 1UL, 1UL ]

  /// <summary>
  /// divduo. sets CR0 from the quotient and XER[SO]. Values from qemu-ppc64
  /// -cpu power10.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC64] DIVDUO. records in CR0``() =
    let max = 0x7fffffffffffffffUL
    (* divduo. r5, r6, r7 *)
    expectCR0 "7ca63f93" [ max, 1UL, 0xe00c0000UL, 0xfUL, 0b0101UL ]

  /// <summary>
  /// mulldo. sets CR0 from the product and copies XER[SO] into it after OV
  /// has been ORed in. Values from qemu-ppc64 -cpu power10.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC64] MULLDO. records in CR0``() =
    let min = 0x8000000000000000UL
    (* mulldo. r5, r6, r7 *)
    expectCR0
      "7ca63dd3"
      [ min, UInt64.MaxValue, 0x20040000UL, 0xfUL, 0b1001UL
        3UL, 5UL, 0UL, 0xfUL, 0b0100UL ]

  /// <summary>
  /// Every form that records an overflow sets XER[OV32] (bit 44, kept at bit
  /// 19 here) as OV would be set in 32-bit mode: from the low words for an
  /// add, a subtract and a negate, so 0x7fffffff + 1 sets OV32 alone and
  /// 0x7fffffffffffffff + 1 sets OV alone; the same as OV for a multiply or
  /// a divide. XER is compared whole. Values from qemu-ppc64 -cpu power10.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC64] The overflow forms set OV32 from the low word``() =
    let max, min = 0x7fffffffffffffffUL, 0x8000000000000000UL
    let lowMin = 0xffffffff80000000UL
    (* addo, subfo, addco, addeo, mullwo, divwo, divdo r5, r6, r7;
       nego r5, r6 *)
    let cases =
      [ "7ca63e14", max, 1UL, 0xe00c0000UL, 0xe0040000UL
        "7ca63e14", 0x7fffffffUL, 1UL, 0x20040000UL, 0x200c0000UL
        "7ca63c50", 0x123456789abcdefUL, 0xfedcba9876543210UL, 0UL, 0x80000UL
        "7ca63c14", 0x7fffffffUL, 1UL, 0x20040000UL, 0x80000UL
        "7ca63c14", min, UInt64.MaxValue, 0x20040000UL, 0xe0000000UL
        "7ca63d14", 0x7fffffffUL, 1UL, 0x20040000UL, 0x80000UL
        "7ca63dd6", lowMin, UInt64.MaxValue, 0xa0040000UL, 0xe00c0000UL
        "7ca63fd6", lowMin, UInt64.MaxValue, 0xa0040000UL, 0xe00c0000UL
        "7ca63fd2", min, UInt64.MaxValue, 0x20040000UL, 0xe00c0000UL
        "7ca604d0", lowMin, 0UL, 0xa0040000UL, 0xa00c0000UL
        "7ca604d0", min, 0UL, 0x20040000UL, 0xe0040000UL ]
    for isa in ppc64s do
      for hex, a, b, xer, expected in cases do
        let after = run isa hex [ R6, a; R7, b; XER, xer ]
        expect expected (after XER) $"{hex} {a:x} {nameOf isa}"

  /// <summary>
  /// Every form that sets XER[CA] sets XER[CA32] (bit 45, kept at bit 18
  /// here) as CA would be set in 32-bit mode: from the carry out of the low
  /// word for the carrying adds and subtracts, and the same as CA for the
  /// algebraic shifts. XER is compared whole. Values from qemu-ppc64 -cpu
  /// power10.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC64] The carrying forms set CA32 from the low word``() =
    let max, min = 0x7fffffffffffffffUL, 0x8000000000000000UL
    (* addc, subfze, addme r5, r6, r7; subfic r5, r6, 12;
       sraw, srad r6, r8, r7; srawi r6, r8, 5 *)
    let cases =
      [ "7ca63814", [ R6, max; R7, 1UL ], 0xe00c0000UL, 0xc00c0000UL
        "7ca63814", [ R6, min; R7, UInt64.MaxValue ], 0x20040000UL, ca
        "7ca60190", [ R6, min ], 0x20040000UL, 0x40000UL
        "20a6000c", [ R6, min ], 0x20040000UL, 0x40000UL
        "7ca601d4", [ R6, 0x5555555555555555UL ], 0x40080000UL, 0x600c0000UL
        "7d063e30", [ R8, 0x123456789abcdefUL; R7, 0x10UL ], 0UL, 0x20040000UL
        "7d063e30", [ R8, min; R7, UInt64.MaxValue ], 0x20040000UL, 0UL
        "7d063e34", [ R8, max; R7, 1UL ], 0xe00c0000UL, 0xc0080000UL
        "7d062e70", [ R8, 0x123456789abcdefUL ], 0UL, 0x20040000UL ]
    for isa in ppc64s do
      for hex, given, xer, expected in cases do
        let after = run isa hex ((XER, xer) :: given)
        expect expected (after XER) $"{hex} {nameOf isa}"

  /// <summary>
  /// A 32-bit processor predates OV32 and CA32: bits 44 and 45 of its XER
  /// are reserved, and no form writes them. The 7457 QEMU models drops them
  /// even from mtxer. XER is compared whole. Values from qemu-ppc -cpu 7457.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC32] No form writes OV32 or CA32``() =
    (* addco, addc r5, r6, r7; srawi r6, r8, 5 *)
    let cases =
      [ "7ca63c14", [ R6, 0x7fffffffUL; R7, 1UL ], 0xe0000000UL, 0xc0000000UL
        "7ca63c14", [ R6, 0x80000000UL; R7, 0xffffffffUL ], ca, 0xe0000000UL
        "7ca63814", [ R6, 0x7fffffffUL; R7, 1UL ], 0xe0000000UL, 0xc0000000UL
        "7d062e70", [ R8, 0x89abcdefUL ], 0UL, ca ]
    for hex, given, xer, expected in cases do
      let after = run ppc32 hex ((XER, xer) :: given)
      expect expected (after XER) hex

  /// <summary>
  /// twi and tw compare the low word of rA with the sign-extended SI or with
  /// the low word of rB, and trap when a comparison their TO field names
  /// holds: TO = 0 names none and never traps, and on a 64-bit processor the
  /// high words take no part, so 0xffffffff0000000c equals 12. The extended
  /// mnemonics (tweqi, twlti, tweq, twgt, twllt here) are the same words.
  /// Values from qemu-ppc64 -cpu power10 and qemu-ppc -cpu 7457.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] TWI and TW trap on the low words TO names``() =
    (* twi 4,r6,12; twi 0,r6,12; twi 16,r6,0; twi 31,r6,0; tw 4,r6,r7;
       tw 8,r6,r7; tw 2,r6,r7 *)
    let cases64 =
      [ "0c86000c", [ R6, 0xffffffff0000000cUL ], true
        "0c86000c", [ R6, 0x10000000dUL ], false
        "0c06000c", [ R6, 0xcUL ], false
        "0e060000", [ R6, 0x80000000UL ], true
        "0e060000", [ R6, 0xffffffff00000001UL ], false
        "0fe60000", [ R6, 7UL ], true
        "7c863808", [ R6, 0x100000005UL; R7, 5UL ], true
        "7c863808", [ R6, 5UL; R7, 6UL ], false
        "7d063808", [ R6, 1UL; R7, 0xffffffff00000002UL ], false
        "7d063808", [ R6, 3UL; R7, 0xffffffff00000002UL ], true
        "7c463808", [ R6, 0x1ffffffffUL; R7, 1UL ], false
        "7c463808", [ R6, 1UL; R7, 0x1ffffffffUL ], true ]
    for isa in ppc64s do
      for hex, given, trapped in cases64 do
        expectTrap trapped isa hex given
    for hex, given, trapped in
      [ "0c86000c", [ R6, 0xcUL ], true
        "0c86000c", [ R6, 0xdUL ], false
        "0c06000c", [ R6, 0xcUL ], false
        "0e060000", [ R6, 0x80000000UL ], true
        "0e060000", [ R6, 1UL ], false ] do
      expectTrap trapped ppc32 hex given

  /// <summary>
  /// lwarx reserves the word it loads, and stwcx. stores only while that
  /// reservation holds and says in CR0[EQ] whether it did; either way it
  /// clears the reservation, so a second stwcx. with no lwarx between fails
  /// and writes nothing -- even where the first stored the very value the
  /// reservation was made over, so that memory still holds it. Values from
  /// QEMU running lwarx r5,0,r6; stwcx. r7,0,r6 and then a second stwcx.
  /// r8,0,r6 in one go, in each byte order.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] STWCX. uses up the reservation LWARX made``() =
    let field = [ CR0_0; CR0_1; CR0_2; CR0_3 ]
    let state = [ R5; R6; R7; R8; ExMonAddr; ExMonVal; RES; XER ] @ field
    let ea = 0x20200080UL
    let reserved = [| 0x11uy; 0x22uy; 0x33uy; 0x44uy |]
    let big = [| 0xaauy; 0xbbuy; 0xccuy; 0xdduy |]
    let word (left: Map<uint64, byte[]>) =
      Array.init 4 (fun i -> left[ea + uint64 i][0])
    (* lwarx r5,0,r6; stwcx. r7,0,r6; stwcx. r8,0,r6 *)
    let lwarx, first, second = "7ca03028", "7ce0312d", "7d00312d"
    for isa, loaded, stored in
      [ ppc32, 0x11223344UL, big
        ppc64, 0x11223344UL, big
        ppc64le, 0x44332211UL, Array.rev big ] do
      let go hexes r7 =
        let given = [ R6, ea; R7, r7; R8, 0x55667788UL ]
        sequence isa hexes state given [ ea, reserved ]
      let after, left = go [ lwarx; first ] 0xaabbccddUL
      expect loaded (after R5) (nameOf isa)
      expect 0b0010UL (cr0 after) (nameOf isa)
      CollectionAssert.AreEqual(stored, word left, nameOf isa)
      let after, left = go [ lwarx; first; second ] loaded
      expect 0UL (cr0 after) (nameOf isa)
      CollectionAssert.AreEqual(reserved, word left, nameOf isa)

  /// <summary>
  /// stwcx. with no reservation fails without touching memory -- it neither
  /// stores nor reads the word it would have stored to -- and records the
  /// failure in CR0, with SO from XER[SO]. Values from QEMU running stwcx.
  /// r7,0,r6 alone.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] STWCX. with no reservation reads and writes nothing``() =
    let field = [ CR0_0, 1UL; CR0_1, 1UL; CR0_2, 1UL; CR0_3, 1UL ]
    (* stwcx. r7, 0, r6 *)
    for isa in [ ppc32; ppc64; ppc64le ] do
      let given = (R6, 0x20200080UL) :: (R7, 0xaabbccddUL) :: field
      let after, memory = exec isa "7ce0312d" given []
      expect 0UL (cr0 after) (nameOf isa)
      expect 0UL (uint64 memory.Count) (nameOf isa)

  /// <summary>
  /// mfxer reads XER, a 32-bit register here, into the low word of rD and
  /// zeroes the rest of it; mtxer writes the low word of rS into XER. A
  /// 32-bit processor keeps no OV32 or CA32, so mtxer drops them there, as
  /// the 7457 does. Values from qemu-ppc64 -cpu power10 and qemu-ppc -cpu
  /// 7457 (mfxer r5; mtxer r8).
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] MFXER and MTXER move XER's word``() =
    for isa in ppc64s do
      for xer in [ 0xe00c0000UL; 0x40080000UL ] do
        let after = run isa "7ca102a6" [ R5, 0xbad0bad0bad0badUL; XER, xer ]
        expect xer (after R5) (nameOf isa)
      for rs, xer in
        [ 0xffffffffe00c007fUL, 0xe00c007fUL
          0x123456789abcdef3UL, 0x9abcdef3UL ] do
        expect xer (run isa "7d0103a6" [ R8, rs ] XER) (nameOf isa)
    expect 0xe0000000UL (run ppc32 "7ca102a6" [ XER, 0xe0000000UL ] R5) "32"
    for rs, xer in [ 0xe00c007fUL, 0xe000007fUL; 0x9abcdef3UL, 0x9ab0def3UL ] do
      expect xer (run ppc32 "7d0103a6" [ R8, rs ] XER) "ppc32"

  /// <summary>
  /// mtspr and mfspr of VRSAVE, a 32-bit SPR, move the low word of rS in and
  /// zero-extend it back out; mfspr of PVR, another, zero-extends what the
  /// processor reports. Values from QEMU running mtvrsave r8; mfvrsave r5,
  /// and mfpvr r5 (which reads 0x00801200 on its power10 and 0x80020102 on
  /// its 7457).
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] MFSPR and MTSPR size a 32-bit SPR to the register``() =
    (* mtvrsave r8; mfvrsave r5; mfpvr r5 *)
    let hexes = [ "7d0043a6"; "7ca042a6" ]
    for isa, rs, saved, pvr in
      [ ppc32, 0xe00c007fUL, 0xe00c007fUL, 0x80020102UL
        ppc64, 0xffffffffe00c007fUL, 0xe00c007fUL, 0x801200UL
        ppc64le, 0x123456789abcdef3UL, 0x9abcdef3UL, 0x801200UL ] do
      let after, _ = sequence isa hexes [ R5; VRSAVE ] [ R8, rs ] []
      expect saved (after R5) (nameOf isa)
      expect pvr (run isa "7cbf42a6" [ PVR, pvr ] R5) (nameOf isa)

  /// <summary>
  /// PVR is read-only, and mtspr naming it is a privileged instruction (the
  /// reference board takes a Privileged program interrupt on it): the word
  /// lifts to that and to no write of PVR.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] MTSPR of PVR does not write it``() =
    (* mtspr 287, r8 *)
    for isa in [ ppc32; ppc64; ppc64le ] do
      let lifted = effects isa "7d1f43a6"
      CollectionAssert.AreEqual([| UnsupportedInstruction |], lifted)

  /// <summary>
  /// bctar goes to TAR with its low two bits cleared where BO says the
  /// counter and the CR bit BI allow it, counting CTR down unless BO2 says
  /// not to, and leaves LR alone. Values from QEMU running mttar r8 and then
  /// the branch, which therefore sits at 0x20100004.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC64] BCTAR branches to TAR``() =
    let nia, tar = 0x20100008UL, 0x20100040UL
    (* bctar 12,2; bctar 4,2; bctar 16,0 *)
    expectTargetBranch
      [ "4d820460", tar, 1UL, 2UL, tar, 1UL, 2UL
        "4d820460", tar, 0UL, 2UL, nia, 1UL, 2UL
        "4c820460", tar + 3UL, 0UL, 2UL, tar, 1UL, 2UL
        "4c820460", tar, 1UL, 2UL, nia, 1UL, 2UL
        "4e000460", tar, 0UL, 2UL, tar, 1UL, 1UL
        "4e000460", tar, 0UL, 1UL, nia, 1UL, 0UL ]

  /// <summary>
  /// bctarl branches as bctar does and leaves the next instruction's address
  /// in LR whether the branch is taken or not. Values from QEMU running
  /// mttar r8 and then the branch, which therefore sits at 0x20100004.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC64] BCTARL branches to TAR and links``() =
    let nia, tar = 0x20100008UL, 0x20100040UL
    (* bctarl 12,2; bctarl 20,0 *)
    expectTargetBranch
      [ "4d820461", tar, 1UL, 2UL, tar, nia, 2UL
        "4d820461", tar + 3UL, 0UL, 2UL, nia, nia, 2UL
        "4e800461", tar, 0UL, 5UL, tar, nia, 5UL ]

  /// <summary>
  /// lqarx loads the aligned quadword into an even-odd register pair -- the
  /// even register the doubleword at EA on a big-endian processor and the one
  /// at EA + 8 on a little-endian one, which byte-reverses the quadword --
  /// and reserves it, so that a stqcx. after it succeeds. Values from QEMU
  /// running lqarx r10,0,r6 and lqarx r10,0,r6; stqcx. r12,0,r6 in each
  /// byte order.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC64] LQARX loads and reserves a quadword``() =
    (* lqarx r10,0,r6; stqcx. r12,0,r6 *)
    let lqarx, stqcx = "7d403228", "7d80316d"
    for isa, r10, r11 in
      [ ppc64, 0x0011223344556677UL, 0x8899aabbccddeeffUL
        ppc64le, 0xffeeddccbbaa9988UL, 0x7766554433221100UL ] do
      let after, _ = quadSequence isa [ lqarx ] quad
      expect r10 (after R10) (nameOf isa)
      expect r11 (after R11) (nameOf isa)
      let after, _ = quadSequence isa [ lqarx; stqcx ] quad
      expect 0b0010UL (cr0 after) (nameOf isa)

  /// <summary>
  /// stqcx. stores an even-odd register pair as lqarx loads one while the
  /// reservation holds and clears it, so a second stqcx. fails and stores
  /// nothing, and one with no reservation touches no memory. Values from
  /// QEMU running lqarx r10,0,r6; stqcx. r12,0,r6; stqcx. r14,0,r6 in each
  /// byte order, and stqcx. r12,0,r6 alone.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC64] STQCX. stores a reserved quadword once``() =
    let ea = 0x20200080UL
    (* lqarx r10,0,r6; stqcx. r12,0,r6; stqcx. r14,0,r6 *)
    let lqarx, first, second = "7d403228", "7d80316d", "7dc0316d"
    for isa, low, high in
      [ ppc64, 0x1111111122222222UL, 0x3333333344444444UL
        ppc64le, 0x4444444433333333UL, 0x2222222211111111UL ] do
      let after, left = quadSequence isa [ lqarx; first ] quad
      expect 0b0010UL (cr0 after) (nameOf isa)
      expect low (doubleword left ea) (nameOf isa)
      expect high (doubleword left (ea + 8UL)) (nameOf isa)
      let after, left = quadSequence isa [ lqarx; first; second ] quad
      expect 0UL (cr0 after) (nameOf isa)
      expect low (doubleword left ea) (nameOf isa)
      expect high (doubleword left (ea + 8UL)) (nameOf isa)
      let after, left = quadSequence isa [ first ] []
      expect 0UL (cr0 after) (nameOf isa)
      expect 0UL (uint64 left.Count) (nameOf isa)

  /// <summary>
  /// lq loads the quadword at EA into an even-odd register pair -- the even
  /// register the doubleword at EA on a big-endian processor and the one at
  /// EA + 8 on a little-endian one, which byte-reverses the quadword. rA may
  /// name the odd register, which the load then overwrites; a quadword off a
  /// sixteen-byte boundary loads all the same, as it does in QEMU's user
  /// mode. Values from QEMU running lq r10,16(r6) and lq r10,0(r11) in each
  /// byte order (specs lq, lqle).
  /// </summary>
  [<TestMethod>]
  member _.``[PPC64] LQ loads a quadword into a pair``() =
    let aligned, off = 0x20200070UL, 0x20200078UL
    (* lq r10,16(r6); lq r10,0(r11) *)
    let bigLoads =
      [ "e1460010", aligned, 0x0011223344556677UL, 0x8899aabbccddeeffUL
        "e14b0000", 0UL, 0x0011223344556677UL, 0x8899aabbccddeeffUL
        "e1460010", off, 0x8899aabbccddeeffUL, 0x0123456789abcdefUL ]
    let littleLoads =
      [ "e1460010", aligned, 0xffeeddccbbaa9988UL, 0x7766554433221100UL
        "e14b0000", 0UL, 0xffeeddccbbaa9988UL, 0x7766554433221100UL
        "e1460010", off, 0xefcdab8967452301UL, 0xffeeddccbbaa9988UL ]
    for isa, loads in [ ppc64, bigLoads; ppc64le, littleLoads ] do
      for hex, r6, r10, r11 in loads do
        let given = [ R6, r6; R11, 0x20200080UL ]
        let after, _ = sequence isa [ hex ] [ R10; R11 ] given pairMemory
        expect r10 (after R10) $"{hex} {r6:x} {nameOf isa}"
        expect r11 (after R11) $"{hex} {r6:x} {nameOf isa}"

  /// <summary>
  /// stq stores an even-odd register pair as lq loads one, off a
  /// sixteen-byte boundary as well. Values from QEMU running stq r12,8(r6)
  /// and stq r12,16(r6) in each byte order (specs lq, lqle).
  /// </summary>
  [<TestMethod>]
  member _.``[PPC64] STQ stores a pair as a quadword``() =
    let ea = 0x20200080UL
    let pair = [ R12, 0x1111111122222222UL; R13, 0x3333333344444444UL ]
    (* stq r12,8(r6); stq r12,16(r6) *)
    for isa, first, second in
      [ ppc64, 0x1111111122222222UL, 0x3333333344444444UL
        ppc64le, 0x4444444433333333UL, 0x2222222211111111UL ] do
      for hex, at in [ "f986000a", ea; "f9860012", ea + 8UL ] do
        let given = (R6, 0x20200078UL) :: pair
        let _, left = sequence isa [ hex ] [] given pairMemory
        expect first (doubleword left at) $"{hex} {nameOf isa}"
        expect second (doubleword left (at + 8UL)) $"{hex} {nameOf isa}"

  /// <summary>
  /// rfebb S sets BESCR[GE], its most significant bit, to S and returns to
  /// EBBRR with its low two bits cleared (Book II 7.3). The reference cannot
  /// run it: QEMU's user mode leaves the event-based branch facility off, as
  /// Linux does until a process asks for it, and stops on its registers.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC64] RFEBB returns to EBBRR and sets BESCR[GE] to S``() =
    (* rfebb 0; rfebb 1 *)
    for isa in ppc64s do
      for hex, bescr, after in
        [ "4c000124", 0x8000000000000005UL, 5UL
          "4c000924", 5UL, 0x8000000000000005UL ] do
        let given = [ EBBRR, 0x20100043UL; BESCR, bescr ]
        let state = jump isa hex 0x20100000UL given
        expect 0x20100040UL (state IAR) (nameOf isa)
        expect after (state BESCR) (nameOf isa)

  /// <summary>
  /// mfbhrbe reads an entry of the branch history rolling buffer. How many
  /// entries there are is the implementation's choice (Book I 2.8); this one
  /// keeps none, as nothing here records branches, so every entry reads as
  /// the zero the ISA gives for an entry past the last one. The reference
  /// cannot run it: QEMU's user mode leaves the facility off.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC64] MFBHRBE reads every entry as zero``() =
    (* mfbhrbe r5, 0; mfbhrbe r5, 31 *)
    for isa in ppc64s do
      for hex in [ "7ca0025c"; "7ca0fa5c" ] do
        expect 0UL (run isa hex [ R5, 0xbad0bad0bad0badUL ] R5) hex

  /// <summary>
  /// clrbhrb clears the branch history rolling buffer, which this model
  /// keeps empty, so it changes no register and no memory. The reference
  /// cannot run it: QEMU's user mode leaves the facility off.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC64] CLRBHRB changes nothing``() =
    (* clrbhrb *)
    for isa in ppc64s do
      expect 0UL (uint64 (writes isa "7c00035c").Length) (nameOf isa)

  /// <summary>
  /// icbt is a hint that an instruction cache block will soon be needed; it
  /// changes no register and no memory. QEMU refuses it outside Book E
  /// (deviations/ppc64/icbt.c), so the expectation is the ISA's.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] ICBT changes nothing``() =
    (* icbt 0, r6, r7; icbt 2, r6, r7 *)
    for isa in all3 do
      for hex in [ "7c06382c"; "7c46382c" ] do
        expect 0UL (uint64 (writes isa hex).Length) $"{hex} {nameOf isa}"

  /// <summary>
  /// mtspr and mfspr of TAR (815) move all of rS in and out on a 64-bit
  /// processor; a 32-bit one has no TAR, and the 7457 refuses both as illegal
  /// instructions. Values from QEMU running mttar r8; mftar r5.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] MTSPR and MFSPR move TAR on a 64-bit processor``() =
    (* mttar r8; mftar r5 *)
    let hexes = [ "7d0fcba6"; "7cafcaa6" ]
    for isa in ppc64s do
      for rs in [ 0xffffffffe00c007fUL; 0x123456789abcdef3UL ] do
        let after, _ = sequence isa hexes [ R5; TAR ] [ R8, rs ] []
        expect rs (after R5) (nameOf isa)
    for hex in hexes do
      let undefined = effects ppc32 hex
      CollectionAssert.AreEqual([| UndefinedInstruction |], undefined, hex)

  /// <summary>
  /// The event-based branch registers. mtspr 806 writes BESCR whole; 800 and
  /// 801 set the bits of BESCR, or of its upper word, that rS's ones name,
  /// and 802 and 803 reset them; mfspr of 800, 802 and 806 reads BESCR and
  /// of 801 and 803 its upper word; EBBHR (804) and EBBRR (805) are plain
  /// registers (Book II 7.2). The reference cannot run them: QEMU's user mode
  /// leaves the facility off and stops on its registers.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC64] MTSPR and MFSPR of the event-based branch registers``() =
    let bescr = 0x0000ff00000000f0UL
    (* mtspr 800..806, r8; mfspr r5, 800..806 *)
    let writes =
      [ "7d00cba6", 0x0000000100000001UL, 0x0000ff01000000f1UL
        "7d01cba6", 0x0000000100000001UL, 0x0000ff01000000f0UL
        "7d02cba6", 0x00000f00000000f0UL, 0x0000f00000000000UL
        "7d03cba6", 0x0000000000000f00UL, 0x0000f000000000f0UL
        "7d06cba6", 0x0123456789abcdefUL, 0x0123456789abcdefUL ]
    for isa in ppc64s do
      for hex, rs, after in writes do
        let state = run isa hex [ R8, rs; BESCR, bescr ]
        expect after (state BESCR) $"{hex} {nameOf isa}"
      for hex, read in
        [ "7ca0caa6", bescr
          "7ca1caa6", 0x0000ff00UL
          "7ca2caa6", bescr
          "7ca3caa6", 0x0000ff00UL
          "7ca6caa6", bescr ] do
        expect read (run isa hex [ BESCR, bescr ] R5) $"{hex} {nameOf isa}"
      for mt, mf, reg in
        [ "7d04cba6", "7ca4caa6", EBBHR; "7d05cba6", "7ca5caa6", EBBRR ] do
        let after, _ = sequence isa [ mt; mf ] [ R5; reg ] [ R8, 0x1234UL ] []
        expect 0x1234UL (after R5) $"{mt} {nameOf isa}"

  /// <summary>
  /// bclrl and bcctrl leave the address of the next instruction in LR
  /// whether the branch is taken or not (Book I 2.4, "if LK then LR <- CIA +
  /// 4"), and a taken bclrl goes to the LR it read before writing it. Values
  /// from QEMU, the branch at 0x20100000.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] BCLRL and BCCTRL link whether taken or not``() =
    let at, nia = 0x20100000UL, 0x20100004UL
    let lr, ctr = 0x20100040UL, 0x20100080UL
    (* bclrl 12,2; bcctrl 12,2; bclrl 4,2 *)
    let cases =
      [ "4d820021", 0UL, nia
        "4d820021", 1UL, lr
        "4d820421", 0UL, nia
        "4d820421", 1UL, ctr
        "4c820021", 0UL, lr
        "4c820021", 1UL, nia ]
    for isa in [ ppc32; ppc64; ppc64le ] do
      for hex, eq, next in cases do
        let after = jump isa hex at [ LR, lr; CTR, ctr; CR0_2, eq ]
        let case = $"{hex} {eq} {nameOf isa}"
        expect next (after IAR) case
        expect nia (after LR) case

  /// <summary>
  /// divwe puts the low word of rA above a word of zeros and divides that by
  /// the low word of rB as signed integers, the high words of a 64-bit
  /// register taking no part; the quotient fills a 64-bit register by sign
  /// extension, as QEMU leaves it (the ISA leaves the high word undefined).
  /// Values from qemu-ppc64 -cpu power10 (spec divext); the 32-bit
  /// processor's are the low words of the same, as the 7457 has no extended
  /// divide.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] DIVWE divides rA shifted up a word``() =
    (* divwe r5, r6, r7 *)
    expectR5
      all3
      "7ca63b56"
      [ 1UL, 3UL, 0x55555555UL
        UInt64.MaxValue, 4UL, 0xffffffffc0000000UL
        1UL, 0xfffffffffffffffdUL, 0xffffffffaaaaaaabUL
        0xffffffff00000001UL, 0x500000003UL, 0x55555555UL ]

  /// <summary>
  /// divwe. sets CR0 from the quotient of divwe and from XER[SO], which a
  /// zero divisor leaves the only defined bit of it. Values from qemu-ppc64
  /// -cpu power10 (spec divext).
  /// </summary>
  [<TestMethod>]
  member _.``[PPC64] DIVWE. records in CR0``() =
    (* divwe. r5, r6, r7 *)
    expectCR0
      "7ca63b57"
      [ 1UL, 3UL, 0UL, 0xfUL, 0b0100UL
        1UL, 3UL, 0xe00c0000UL, 0xfUL, 0b0101UL
        UInt64.MaxValue, 4UL, 0UL, 0xfUL, 0b1000UL
        5UL, 0UL, 0UL, 1UL, 0UL
        5UL, 0UL, 0xe00c0000UL, 1UL, 1UL ]

  /// <summary>
  /// divweo sets OV and OV32 where the quotient of divwe is past the signed
