    expectR5 ppc64s "7ca63f56" [ 1UL, 3UL, 0x55555555UL ]
    expectXER
      "7ca63f56"
      [ 1UL, 3UL, 0xe00c0000UL, 0xa0040000UL
        UInt64.MaxValue, 4UL, 0xe00c0000UL, 0xa0040000UL
        5UL, 0UL, 0UL, 0xc0080000UL
        5UL, 0UL, 0xe00c0000UL, 0xe00c0000UL ]

