    expectUnary
      all3
      "7d060274"
      [ 0x0033956300993908UL, 0x0006e6e300067caeUL
        0x0015817600414002UL, 0x000360f600085002UL
        0x0099999900000000UL, 0x0003fcff00000000UL ]

