  /// <summary>
  /// setb gives -1 where the CR field it names says LT, 1 where it says GT
  /// and not LT, and 0 otherwise. Values from qemu-ppc64 -cpu power10 (setb
  /// r5, cr3 over CR 0x2468ace0, 0x13579bdf and 0); the 32-bit processor's
  /// from the low words of the same.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] SETB turns a CR field into -1, 1 or 0``() =
    (* setb r5, cr3 *)
    for isa in [ ppc32; ppc64; ppc64le ] do
      for field, r in [ 0x8UL, ones isa; 0x7UL, 1UL; 0UL, 0UL ] do
        let bit n = (field >>> (3 - n)) &&& 1UL
        let given = [ CR3_0, bit 0; CR3_1, bit 1; CR3_2, bit 2; CR3_3, bit 3 ]
        expect r (run isa "7cac0100" given R5) $"{field} {nameOf isa}"

  /// <summary>
  /// cmprb sets the CR field it names to 0b0100 where the low byte of rA lies
  /// within the bounds in rB's low two bytes -- or, for L = 1, within those
  /// or the ones in the two above them -- and to zero where it does not.
  /// Values from qemu-ppc64 -cpu power10 (spec p9: the isdigit and isalpha
  /// ranges).
  /// </summary>
  [<TestMethod>]
  member _.``[PPC64] CMPRB tests a byte against one or two ranges``() =
    let digits, letters = 0x3930UL, 0x7a615a41UL
    (* cmprb cr2,0,r6,r7; cmprb cr2,1,r6,r7 *)
    let cases =
      [ "7d063980", 0x35UL, digits, 0b0100UL
        "7d063980", 0x30UL, digits, 0b0100UL
        "7d063980", 0x2fUL, digits, 0UL
        "7d063980", 0x3aUL, digits, 0UL
        "7d063980", 0x7aUL, letters, 0UL
        "7d263980", 0x7aUL, letters, 0b0100UL
        "7d263980", 0x5bUL, letters, 0UL
        "7d263980", 0xffffffffffffff61UL, letters, 0b0100UL ]
    for isa in ppc64s do
      for hex, ra, rb, field in cases do
        let after = run isa hex [ R6, ra; R7, rb ]
        expect field (cr2 after) $"{hex} {ra:x} {nameOf isa}"

  /// <summary>
  /// cmpeqb sets the CR field it names to 0b0100 where the low byte of rA
  /// equals any byte of rB and to zero where it equals none. Values from
  /// qemu-ppc64 -cpu power10 (spec p9: the whitespace bytes).
  /// </summary>
  [<TestMethod>]
  member _.``[PPC64] CMPEQB tests a byte against eight``() =
    let spaces = 0x0909090a0b0c0d20UL
    (* cmpeqb cr2,r6,r7 *)
    for isa in ppc64s do
      for ra, field in
        [ 0x20UL, 0b0100UL
          0x41UL, 0UL
          0xffffff0bUL, 0b0100UL
          0x100UL, 0UL ] do
        let after = run isa "7d0639c0" [ R6, ra; R7, spaces ]
        expect field (cr2 after) $"{ra:x} {nameOf isa}"

  /// <summary>
  /// mcrxrx copies OV, OV32, CA and CA32 into the CR field it names. Values
  /// from qemu-ppc64 -cpu power10 (mcrxrx cr2).
  /// </summary>
  [<TestMethod>]
  member _.``[PPC64] MCRXRX copies OV, OV32, CA and CA32 into a field``() =
    (* mcrxrx cr2 *)
    for isa in ppc64s do
      for xer, field in
        [ 0xe00c0000UL, 0b1111UL
          0x40080000UL, 0b1100UL
          0x20040000UL, 0b0011UL
          so, 0UL ] do
        let after = run isa "7d000480" [ XER, xer ]
        let cr2 =
          (after CR2_0 <<< 3) ||| (after CR2_1 <<< 2) ||| (after CR2_2 <<< 1)
          ||| after CR2_3
        expect field cr2 $"{xer:x} {nameOf isa}"

  /// <summary>
  /// addex adds rA, rB and OV and keeps the carry out in OV -- out of the
  /// register, so out of the low word on a 32-bit processor -- and the carry
  /// out of the low word in OV32 on a 64-bit one, leaving SO, CA and CA32
  /// alone. Values from qemu-ppc64 -cpu power10 (the words file and spec
  /// p9); the 32-bit processor's OV is the 64-bit one's OV32.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] ADDEX adds with OV as the carry``() =
    let max, min = 0x7fffffffffffffffUL, 0x8000000000000000UL
    (* addex r5, r6, r7, 0 *)
    let cases =
      [ max, 1UL, 0xe00c0000UL, 0x8000000000000001UL, 0xa00c0000UL
        min, UInt64.MaxValue, 0x20040000UL, max, 0x60040000UL
        0xffffffffUL, 1UL, ov, 0x100000001UL, 0x80000UL
        UInt64.MaxValue, 0UL, ov, 0UL, 0x40080000UL
        1UL, 2UL, 0xc0080000UL, 4UL, so ]
    for isa in ppc64s do
      for a, b, xer, sum, xerAfter in cases do
        let after = run isa "7ca63954" [ R6, a; R7, b; XER, xer ]
        expect sum (after R5) $"{a:x} {nameOf isa}"
        expect xerAfter (after XER) $"{a:x} {nameOf isa}"
    let after = run ppc32 "7ca63954" [ R6, 0xffffffffUL; R7, 1UL; XER, ov ]
    expect 1UL (after R5) "ppc32"
    expect ov (after XER) "ppc32"

  /// <summary>
  /// addpcis adds D, shifted up sixteen bits and sign-extended, to the
  /// address of the next instruction. Values from qemu-ppc64 -cpu power10,
  /// the word at 0x20100000 (spec p9); the 32-bit processor's are the low
  /// words of the same.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] ADDPCIS adds D to the next instruction's address``() =
    (* addpcis r5, 1; -1; 0x7fff; -0x8000; 0 *)
    let cases =
      [ "4ca00005", 0x20110004UL
        "4cbfffc5", 0x200f0004UL
        "4cbf7fc5", 0xa00f0004UL
        "4ca08004", 0xffffffffa0100004UL
        "4ca00004", 0x20100004UL ]
    for isa in [ ppc32; ppc64; ppc64le ] do
      for hex, rt in cases do
        let after = jump isa hex 0x20100000UL []
        expect (rt &&& ones isa) (after R5) $"{hex} {nameOf isa}"

  /// <summary>
  /// darn may fail, and reports a failure as all ones (Book I 3.3.9); this
  /// model has no source of randomness and always does, which software is
  /// expected to answer by retrying and then using a generator of its own.
  /// QEMU returns random numbers, so the value is the manual's error code
  /// rather than a measurement.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC64] DARN reports the error value``() =
    (* darn r5, 1; darn r5, 0; darn r5, 2 *)
    for isa in ppc64s do
      for hex in [ "7ca105e6"; "7ca005e6"; "7ca205e6" ] do
        expect UInt64.MaxValue (run isa hex [ R5, 0x1234UL ] R5) hex

  /// <summary>
  /// brd reverses the bytes of rS. Values from qemu-ppc64 -cpu power10 (the
  /// words file and spec isa31).
  /// </summary>
  [<TestMethod>]
  member _.``[PPC64] BRD reverses the bytes of a doubleword``() =
    (* brd r6, r8 *)
    expectUnary
      ppc64s
      "7d060176"
      [ 0x0123456789abcdefUL, 0xefcdab8967452301UL
        0x80000000000000ffUL, 0xff00000000000080UL
        0xffffffff80000000UL, 0x80ffffffffUL ]

  /// <summary>
  /// brw reverses the bytes of each word of rS. Values from qemu-ppc64 -cpu
  /// power10 (the words file and spec isa31); the 32-bit processor's are the
  /// low words of the same, as the 7457 has no brw.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] BRW reverses the bytes of each word``() =
    (* brw r6, r8 *)
    expectUnary
      all3
      "7d060136"
      [ 0x0123456789abcdefUL, 0x67452301efcdab89UL
        0xffffffff80000000UL, 0xffffffff00000080UL ]

  /// <summary>
  /// brh reverses the bytes of each halfword of rS. Values from qemu-ppc64
  /// -cpu power10 (the words file and spec isa31); the 32-bit processor's are
  /// the low words of the same, as the 7457 has no brh.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] BRH reverses the bytes of each halfword``() =
    (* brh r6, r8 *)
    expectUnary
      all3
      "7d0601b6"
      [ 0x0123456789abcdefUL, 0x23016745ab89efcdUL
        0xffffffff80000000UL, 0xffffffff00800000UL ]

  /// <summary>
  /// pextd packs the bits of rS under the ones of rB into the low bits of
  /// rA, keeping their order. Values from qemu-ppc64 -cpu power10 (the words
  /// file and spec isa31).
  /// </summary>
  [<TestMethod>]
  member _.``[PPC64] PEXTD packs the bits under a mask``() =
    let beef = 0xdeadbeefcafebabeUL
    (* pextd r6, r8, r7 *)
    expectBinary
      ppc64s
      "7d063978"
      [ 0x0123456789abcdefUL, 0xff00ff00f0f0f0f0UL, 0x1458aceUL
        beef, 0x8000000000000001UL, 2UL
        beef, 0xffff0000UL, 0xcafeUL
        0xfffffffffffffff0UL, 0xff00ff00ff00ffUL, 0xfffffff0UL
        0xf0000000000000UL, 0xff0000000000ff0UL, 0xf00UL
        beef, UInt64.MaxValue, beef
        0x1234UL, 0UL, 0UL ]

  /// <summary>
  /// pdepd spreads the low bits of rS over the positions of the ones of rB,
  /// lowest first, and clears the rest. Values from qemu-ppc64 -cpu power10
  /// (the words file and spec isa31).
  /// </summary>
  [<TestMethod>]
  member _.``[PPC64] PDEPD spreads bits over a mask``() =
    let a, beef = 0x0123456789abcdefUL, 0xdeadbeefcafebabeUL
    (* pdepd r6, r8, r7 *)
    expectBinary
      ppc64s
      "7d063938"
      [ a, 0xff00ff00f0f0f0f0UL, 0x8900ab00c0d0e0f0UL
        beef, 0x8000000000000001UL, 0x8000000000000000UL
        beef, 0xffff0000UL, 0xbabe0000UL
        0xfffffffffffffff0UL, 0xff00ff00ff00ffUL, 0xff00ff00ff00f0UL
        a, 0xfedcba9876543210UL, 0x88c89a8066503210UL ]

  /// <summary>
  /// cfuged packs the bits of rS under the ones of rB to the right of rA and
  /// the others to the left, each keeping their order. Values from
  /// qemu-ppc64 -cpu power10 (the words file and spec isa31).
  /// </summary>
  [<TestMethod>]
  member _.``[PPC64] CFUGED separates the bits under a mask``() =
    let beef, ends = 0xdeadbeefcafebabeUL, 0x8000000000000001UL
    (* cfuged r6, r8, r7 *)
    expectBinary
      ppc64s
      "7d0639b8"
      [ 0x0123456789abcdefUL, 0xff00ff00f0f0f0f0UL, 0x23679bdf01458aceUL
        beef, ends, 0xbd5b7ddf95fd757eUL
        beef, 0xffff0000UL, 0xdeadbeefbabecafeUL
        ends, ends, 3UL
        0x5555555555555555UL, 0xaaaaaaaaaaaaaaaaUL, 0xffffffff00000000UL
        beef, UInt64.MaxValue, beef
        0x1234UL, 0UL, 0x1234UL ]

  /// <summary>
  /// cntlzdm counts the zeros of rS under the ones of rB from the most
  /// significant end up to the first one there, giving the number of ones in
  /// rB where there is none. Values from qemu-ppc64 -cpu power10 (the words
  /// file and spec isa31).
  /// </summary>
  [<TestMethod>]
  member _.``[PPC64] CNTLZDM counts leading zeros under a mask``() =
    (* cntlzdm r6, r8, r7 *)
    expectBinary
      ppc64s
      "7d063876"
      [ 0x0123456789abcdefUL, 0xff00ff00f0f0f0f0UL, 7UL
        0xdeadbeefcafebabeUL, 0x8000000000000001UL, 0UL
        0UL, 0xf0fUL, 8UL
        0xf0000000000000UL, 0xff0000000000ff0UL, 4UL
        0UL, UInt64.MaxValue, 0x40UL
        0x5555555555555555UL, 0xaaaaaaaaaaaaaaaaUL, 0x20UL ]

  /// <summary>
  /// cnttzdm counts the zeros of rS under the ones of rB from the least
  /// significant end up to the first one there, giving the number of ones in
  /// rB where there is none. Values from qemu-ppc64 -cpu power10 (the words
  /// file and spec isa31).
  /// </summary>
  [<TestMethod>]
  member _.``[PPC64] CNTTZDM counts trailing zeros under a mask``() =
    let ends = 0x8000000000000001UL
    (* cnttzdm r6, r8, r7 *)
    expectBinary
      ppc64s
      "7d063c76"
      [ 0x0123456789abcdefUL, 0xff00ff00f0f0f0f0UL, 1UL
        0xdeadbeefcafebabeUL, ends, 1UL
        ends, ends, 0UL
        0xfffffffffffffff0UL, 0xff00ff00ff00ffUL, 4UL
        0xf0000000000000UL, 0xff0000000000ff0UL, 8UL
        0x8000000000000000UL, UInt64.MaxValue, 0x3fUL
        0UL, UInt64.MaxValue, 0x40UL ]

  /// <summary>
  /// setbc gives 1 where the CR bit BI is set and 0 where it is clear.
  /// Values from qemu-ppc64 -cpu power10 (the words file, BI = 4*cr2+gt).
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] SETBC gives 1 for a set CR bit``() =
    (* setbc r5, 4*cr2+gt *)
    expectFromCRBit "7ca90300" one none

  /// <summary>
  /// setbcr gives 0 where the CR bit BI is set and 1 where it is clear.
  /// Values from qemu-ppc64 -cpu power10 (the words file, BI = 4*cr2+gt).
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] SETBCR gives 1 for a clear CR bit``() =
    (* setbcr r5, 4*cr2+gt *)
    expectFromCRBit "7ca90340" none one

  /// <summary>
  /// setnbc gives -1 where the CR bit BI is set and 0 where it is clear.
  /// Values from qemu-ppc64 -cpu power10 (the words file, BI = 4*cr2+gt);
  /// the 32-bit processor's -1 is the low word of the same.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] SETNBC gives -1 for a set CR bit``() =
    (* setnbc r5, 4*cr2+gt *)
    expectFromCRBit "7ca90380" ones none

  /// <summary>
  /// setnbcr gives 0 where the CR bit BI is set and -1 where it is clear.
  /// Values from qemu-ppc64 -cpu power10 (the words file, BI = 4*cr2+gt);
  /// the 32-bit processor's -1 is the low word of the same.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] SETNBCR gives -1 for a clear CR bit``() =
    (* setnbcr r5, 4*cr2+gt *)
    expectFromCRBit "7ca903c0" none ones

  /// <summary>
  /// popcntb counts the ones of each byte of rS into that byte of rA. The
  /// ISA gives it to a 32-bit processor too. Values from qemu-ppc64 -cpu
  /// power10 (spec gate32); the 7457 refuses it, so the 32-bit expectations
  /// are the low words.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] POPCNTB counts the ones of each byte``() =
    (* popcntb r6, r8 *)
    expectUnary
      all3
      "7d0600f4"
      [ 0x8000000180ff0f01UL, 0x100000101080401UL
        0x1234567808ff0f01UL, 0x203040401080401UL ]

  /// <summary>
  /// popcntw counts the ones of each word of rS into that word of rA. The
  /// ISA gives it to a 32-bit processor too. Values from qemu-ppc64 -cpu
  /// power10 (spec gate32); the 32-bit expectations are the low words.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] POPCNTW counts the ones of each word``() =
    (* popcntw r6, r8 *)
    expectUnary
      all3
      "7d0602f4"
      [ 0x8000000180ff0f01UL, 0x20000000eUL
        0x1234567808ff0f01UL, 0xd0000000eUL ]

  /// <summary>
  /// prtyw puts the parity of the low bits of each word's bytes in the low
  /// bit of that word of rA. The ISA gives it to a 32-bit processor too.
  /// Values from qemu-ppc64 -cpu power10 (spec gate32); the 32-bit
  /// expectations are the low words.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] PRTYW gives the parity of each word's bytes``() =
    (* prtyw r6, r8 *)
    expectUnary
      all3
      "7d060134"
      [ 0x8000000180ff0f01UL, 0x100000001UL
        0x1234567808ff0f01UL, 1UL ]

  /// <summary>
  /// cmpb sets each byte of rA to all ones where the bytes of rS and rB
  /// there are equal and to zero where they are not. The ISA gives it to a
  /// 32-bit processor too. Values from qemu-ppc64 -cpu power10 (the words
  /// file and spec gate32); the 32-bit expectations are the low words.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] CMPB compares bytes``() =
    let a = 0x8000000180ff0f01UL
    (* cmpb r6, r8, r7 *)
    expectBinary
      all3
      "7d063bf8"
      [ a, 3UL, 0xffff0000000000UL
        0x1234567808ff0f01UL, a, 0xffffffUL
        1UL, 0x80000000UL, 0xffffffff00ffff00UL ]

  /// <summary>
  /// lbarx loads a byte and reserves it, so that an stbcx. after it
  /// succeeds. The ISA gives it to a 32-bit processor too. Values from
  /// qemu-ppc64 -cpu power10 running lbarx r5,0,r6 and lbarx r5,0,r6;
  /// stbcx. r7,0,r6 (specs gate32, gate32le); the 7457 refuses it, so the
  /// 32-bit expectations are the big-endian 64-bit processor's.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] LBARX loads and reserves a byte``() =
    (* lbarx r5,0,r6; stbcx. r7,0,r6 *)
    for isa in all3 do
      let after, _ = smallReserve isa [ "7ca03068" ]
      expect 0x88UL (after R5) (nameOf isa)
      let after, _ = smallReserve isa [ "7ca03068"; "7ce0356d" ]
      expect 0b0010UL (cr0 after) (nameOf isa)

  /// <summary>
  /// lharx loads a halfword in the processor's byte order and reserves it,
  /// so that an sthcx. after it succeeds. The ISA gives it to a 32-bit
  /// processor too. Values from qemu-ppc64 -cpu power10 running lharx
  /// r5,0,r6 and lharx r5,0,r6; sthcx. r7,0,r6 (specs gate32, gate32le);
  /// the 32-bit expectations are the big-endian 64-bit processor's.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] LHARX loads and reserves a halfword``() =
    (* lharx r5,0,r6; sthcx. r7,0,r6 *)
    for isa, half in [ ppc32, 0x8899UL; ppc64, 0x8899UL; ppc64le, 0x9988UL ] do
      let after, _ = smallReserve isa [ "7ca030e8" ]
      expect half (after R5) (nameOf isa)
      let after, _ = smallReserve isa [ "7ca030e8"; "7ce035ad" ]
      expect 0b0010UL (cr0 after) (nameOf isa)

  /// <summary>
  /// stbcx. stores the low byte of rS while the reservation lbarx made holds
  /// and clears it, so a second one stores nothing. The ISA gives it to a
  /// 32-bit processor too. Values from qemu-ppc64 -cpu power10 running
  /// lbarx r5,0,r6; stbcx. r7,0,r6; stbcx. r7,0,r6 (specs gate32,
  /// gate32le); the 32-bit expectations are the big-endian 64-bit
  /// processor's.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] STBCX. stores a reserved byte once``() =
    let ea = 0x20200080UL
    (* lbarx r5,0,r6; stbcx. r7,0,r6 *)
    let load, store = "7ca03068", "7ce0356d"
    for isa in all3 do
      let after, left = smallReserve isa [ load; store ]
      expect 0b0010UL (cr0 after) (nameOf isa)
      expect 0x0199aabbUL (valueAt left ea 4) (nameOf isa)
      let after, left = smallReserve isa [ load; store; store ]
      expect 0UL (cr0 after) (nameOf isa)
      expect 0x0199aabbUL (valueAt left ea 4) (nameOf isa)

  /// <summary>
  /// sthcx. stores the low halfword of rS in the processor's byte order
  /// while the reservation lharx made holds and clears it, so a second one
  /// stores nothing. The ISA gives it to a 32-bit processor too. Values from
  /// qemu-ppc64 -cpu power10 running lharx r5,0,r6; sthcx. r7,0,r6; sthcx.
  /// r7,0,r6 (specs gate32, gate32le); the 32-bit expectations are the
  /// big-endian 64-bit processor's.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] STHCX. stores a reserved halfword once``() =
    let ea = 0x20200080UL
    (* lharx r5,0,r6; sthcx. r7,0,r6 *)
    let load, store = "7ca030e8", "7ce035ad"
    for isa, word in
      [ ppc32, 0x0f01aabbUL; ppc64, 0x0f01aabbUL; ppc64le, 0x010faabbUL ] do
      let after, left = smallReserve isa [ load; store ]
      expect 0b0010UL (cr0 after) (nameOf isa)
      expect word (valueAt left ea 4) (nameOf isa)
      let after, left = smallReserve isa [ load; store; store ]
      expect 0UL (cr0 after) (nameOf isa)
      expect word (valueAt left ea 4) (nameOf isa)
  /// <summary>
  /// dcbt is a hint, whatever its TH, and changes no register and no
  /// memory. QEMU runs every TH tested (0, 1, 8, 16, 17; spec cachesync).
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] DCBT changes nothing whatever its TH``() =
    (* dcbt r6, r7; dcbt r6, r7, 1; dcbt r6, r7, 16 *)
    for isa in all3 do
      for hex in [ "7c063a2c"; "7c263a2c"; "7e063a2c" ] do
        expect 0UL (uint64 (writes isa hex).Length) $"{hex} {nameOf isa}"

  /// <summary>
  /// dcbtst is a hint, whatever its TH, and changes no register and no
  /// memory. QEMU runs every TH tested (0, 1, 16; spec cachesync).
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] DCBTST changes nothing whatever its TH``() =
    (* dcbtst r6, r7; dcbtst r6, r7, 1; dcbtst r6, r7, 16 *)
    for isa in all3 do
      for hex in [ "7c0639ec"; "7c2639ec"; "7e0639ec" ] do
        expect 0UL (uint64 (writes isa hex).Length) $"{hex} {nameOf isa}"

  /// <summary>
  /// dcbf flushes a cache block this model does not keep, so for every L
  /// the ISA defines -- 0, 1, 3, 4 and 6 -- it changes no register and no
  /// memory. QEMU 8.2.2 runs only L = 0 and 1 and refuses the others (spec
  /// cachesync, deviations/ppc64/dcbfps.c); the manual wins.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] DCBF changes nothing for every L``() =
    (* dcbf r6, r7, L for L = 0, 1, 3, 4, 6 *)
    let words = [ "7c0638ac"; "7c2638ac"; "7c6638ac"; "7c8638ac"; "7cc638ac" ]
    for isa in all3 do
      for hex in words do
        expect 0UL (uint64 (writes isa hex).Length) $"{hex} {nameOf isa}"

  /// <summary>
  /// ptesync orders page table updates against later accesses; one
  /// processor running one instruction at a time has nothing to order, so
  /// it changes no register and no memory. QEMU runs it (spec cachesync).
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] PTESYNC changes nothing``() =
    (* sync 2, 0 *)
    for isa in all3 do
      expect 0UL (uint64 (writes isa "7c4004ac").Length) (nameOf isa)

  /// <summary>
  /// phwsync is the heavyweight barrier extended to persistent storage; with
  /// nothing to order it changes no register and no memory. QEMU 8.2.2
  /// refuses it (spec cachesync, deviations/ppc64/phwsync.c); the manual
  /// wins.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] PHWSYNC changes nothing``() =
    (* sync 4, 0 *)
    for isa in all3 do
      expect 0UL (uint64 (writes isa "7c8004ac").Length) (nameOf isa)

  /// <summary>
  /// plwsync is the lightweight barrier extended to persistent storage; with
  /// nothing to order it changes no register and no memory. QEMU 8.2.2
  /// refuses it (spec cachesync, deviations/ppc64/phwsync.c); the manual
  /// wins.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] PLWSYNC changes nothing``() =
    (* sync 5, 0 *)
    for isa in all3 do
      expect 0UL (uint64 (writes isa "7ca004ac").Length) (nameOf isa)

  /// <summary>
  /// stncisync orders stores to storage that is not caching inhibited; with
  /// nothing to order it changes no register and no memory. QEMU 8.2.2
  /// refuses it (spec cachesync, deviations/ppc64/phwsync.c); the manual
  /// wins.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] STNCISYNC changes nothing``() =
    (* sync 1, 1 *)
    for isa in all3 do
      expect 0UL (uint64 (writes isa "7c2104ac").Length) (nameOf isa)

  /// <summary>
  /// stcisync orders stores to caching inhibited storage; with nothing to
  /// order it changes no register and no memory. QEMU 8.2.2 refuses it (spec
  /// cachesync, deviations/ppc64/phwsync.c); the manual wins.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] STCISYNC changes nothing``() =
    (* sync 0, 2 *)
    for isa in all3 do
      expect 0UL (uint64 (writes isa "7c0204ac").Length) (nameOf isa)

  /// <summary>
  /// stsync orders stores; with nothing to order it changes no register and
  /// no memory. QEMU 8.2.2 refuses it (spec cachesync,
  /// deviations/ppc64/phwsync.c); the manual wins.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] STSYNC changes nothing``() =
    (* sync 0, 3 *)
    for isa in all3 do
      expect 0UL (uint64 (writes isa "7c0304ac").Length) (nameOf isa)

  /// <summary>
  /// mtspr and mfspr of PPR (896) move all of rS in and out on a 64-bit
  /// processor. Values from QEMU running mtppr r8; mfppr r5 (spec sprs).
  /// </summary>
  [<TestMethod>]
  member _.``[PPC64] MTSPR and MFSPR move PPR``() =
    (* mtspr 896, r8; mfspr r5, 896 *)
    let hexes = [ "7d00e3a6"; "7ca0e2a6" ]
    for isa in ppc64s do
      for value in [ 0x0123456789abcdefUL; 0xfedcba9876543210UL ] do
        let given = [ R5, 0xbad0badUL; R8, value ]
        let after, _ = sequence isa hexes [ R5; R8; PPR ] given []
        expect value (after R5) $"{value:x} {nameOf isa}"

  /// <summary>
  /// PPR32 (898) is the upper word of PPR (Book II 3.1): mtspr writes the
  /// low word of rS there and leaves the lower word alone, and mfspr reads
  /// it into the low word of rT. QEMU 8.2.2 refuses SPR 898 (spec sprs,
  /// deviations/ppc64/dscr.c), so the expectation is the manual's.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC64] MTSPR and MFSPR move PPR32 through PPR's upper word``() =
    (* mtspr 898, r8; mfspr r5, 898 *)
    for isa in ppc64s do
      let given = [ R8, 0x0123456789abcdefUL; PPR, 0x1122334455667788UL ]
      let after = run isa "7d02e3a6" given
      expect 0x89abcdef55667788UL (after PPR) (nameOf isa)
      let after = run isa "7ca2e2a6" [ PPR, 0x1122334455667788UL ]
      expect 0x11223344UL (after R5) (nameOf isa)

  /// <summary>
  /// DSCR (3) and AMR (13) are registers a program may move in and out
  /// whole (Book III 5.4.4, Figure 19); this model has no UAMOR to mask an
  /// AMR write with, which the ISA leaves to the implementation. QEMU 8.2.2
  /// refuses both SPRs in user mode (spec sprs, deviations/ppc64/dscr.c), so
  /// the expectation is the manual's.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC64] MTSPR and MFSPR move DSCR and AMR``() =
    (* mtspr 3, r8; mfspr r5, 3; mtspr 13, r8; mfspr r5, 13 *)
    for isa in ppc64s do
      for hexes, reg in
        [ [ "7d0303a6"; "7ca302a6" ], DSCR
          [ "7d0d03a6"; "7cad02a6" ], AMR ] do
        let given = [ R5, 0xbad0badUL; R8, 0x0123456789abcdefUL ]
        let after, _ = sequence isa hexes [ R5; R8; reg ] given []
        expect 0x0123456789abcdefUL (after R5) $"{reg} {nameOf isa}"

  /// <summary>
  /// mfspr reads CTRL (136) and SPRG3 (259), which a program may read but
  /// not write: mtspr of those numbers is an illegal instruction. Values
  /// from QEMU, which reads both as zero and refuses both writes (spec
  /// sprs).
  /// </summary>
  [<TestMethod>]
  member _.``[PPC64] MFSPR reads CTRL and SPRG3, MTSPR cannot write them``() =
    (* mfspr r5, 136; mfspr r5, 259; mtspr 136, r8; mtspr 259, r8 *)
    for isa in ppc64s do
      for hex, reg in [ "7ca822a6", CTRL; "7ca342a6", SPRG3 ] do
        let given = [ R5, 0xbad0badUL; reg, 0UL ]
        expect 0UL (run isa hex given R5) $"{hex} {nameOf isa}"
      for hex in [ "7d0823a6"; "7d0343a6" ] do
        let lifted = effects isa hex
        CollectionAssert.AreEqual([| UndefinedInstruction |], lifted, hex)

  /// <summary>
  /// SPRs 808 to 811 are reserved, and accesses to them are no-ops (Book III
  /// 5.4.4, Figure 19): mfspr leaves rT as it was and mtspr writes nothing.
  /// Values from QEMU (spec sprs).
  /// </summary>
  [<TestMethod>]
  member _.``[PPC64] MFSPR and MTSPR of SPRs 808 to 811 do nothing``() =
    (* mfspr r5, 808; mtspr 808, r8 *)
    for isa in ppc64s do
      expect 0UL (uint64 (writes isa "7ca8caa6").Length) (nameOf isa)
      expect 0UL (uint64 (writes isa "7d08cba6").Length) (nameOf isa)

  /// <summary>
  /// The server SPRs -- DSCR, AMR, CTRL, SPRG3, PPR, PPR32 and the reserved
  /// 808 to 811 -- belong to the 64-bit processors; the 7457 refuses mfspr
  /// and mtspr of every one of them as illegal instructions (spec sprs).
  /// </summary>
  [<TestMethod>]
  member _.``[PPC32] MFSPR and MTSPR of the server SPRs are undefined``() =
    let words =
      [ "7ca302a6"
        "7d0303a6"
        "7cad02a6"
        "7ca822a6"
        "7ca342a6"
        "7ca8caa6"
        "7d08cba6"
        "7ca0e2a6"
        "7d00e3a6"
        "7ca2e2a6" ]
    for hex in words do
      CollectionAssert.AreEqual([| UndefinedInstruction |], effects ppc32 hex)

  /// <summary>
  /// lwat applies the function code to the word at (rA) and r11's low word
  /// and puts the old word in r10, zero-extended (Book II 4.5.1, Figure 3).
  /// Values from qemu-ppc64 -cpu power10 (specs amo, amole), except where
  /// QEMU 8.2.2 departs from the manual (deviations/ppc64/lwat.c): it
  /// compares words unsigned for the signed maximum and minimum (FC 5, 7),
  /// sign-extends the 0x80000000 a bounded operation gives, and has fetch
  /// and decrement bounded (FC 28) compare with the word above instead of
  /// the one below.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC64] LWAT updates a word atomically``() =
    let low1, b3 = 0x8000000000000001UL, 0x700000003UL
    (* lwat r10, r6, FC *)
    expectAtomic
      [ ppc64 ]
      0x7d46048cu
      [ 0u, 3UL, blockA, 0xfffffff0UL, 0xfffffff3fffffff0UL
        0u, b3, blockB, 7UL, 0x0000000a00000003UL
        1u, b3, blockB, 7UL, 0x0000000400000003UL
        2u, 3UL, blockA, 0xfffffff0UL, 0xfffffff3fffffff0UL
        3u, 3UL, blockA, 0xfffffff0UL, 0x00000000fffffff0UL
        4u, 3UL, blockA, 0xfffffff0UL, 0xfffffff0fffffff0UL
        5u, 3UL, blockA, 0xfffffff0UL, 0x00000003fffffff0UL
        5u, low1, blockA, 0xfffffff0UL, 0x00000001fffffff0UL
        6u, 3UL, blockA, 0xfffffff0UL, 0x00000003fffffff0UL
        7u, 3UL, blockA, 0xfffffff0UL, 0xfffffff0fffffff0UL
        7u, b3, blockB, 7UL, 0x0000000300000003UL
        8u, 3UL, blockA, 0xfffffff0UL, 0x00000003fffffff0UL
        16u, 3UL, blockA, 0xfffffff0UL, 0x00000099fffffff0UL
        16u, b3, blockB, 7UL, 0x0000009900000003UL
        24u, 3UL, blockA, 0x80000000UL, 0xfffffff0fffffff0UL
        24u, b3, blockB, 7UL, 0x0000000800000003UL
        25u, 3UL, blockA, 0xfffffff0UL, 0xfffffff1fffffff0UL
        25u, b3, blockB, 0x80000000UL, 0x0000000700000003UL
        28u, 3UL, blockA, 0xfffffff0UL, 0xffffffeffffffff0UL
        28u, b3, blockB, 0x80000000UL, 0x0000000700000003UL ]
    expectAtomic
      [ ppc64le ]
      0x7d46048cu
      [ 0u, 3UL, blockA, 0xf0ffffffUL, 0x020000f1fffffff0UL ]

  /// <summary>
  /// ldat applies the function code to the doubleword at (rA) and r11 (and
  /// r12) and puts the old doubleword in r10 (Book II 4.5.1, Figure 3).
  /// Values from qemu-ppc64 -cpu power10 (specs amo, amole), except where
  /// QEMU 8.2.2 departs from the manual (deviations/ppc64/lwat.c): it gives
  /// 0xffffffff80000000 for a bounded operation's 1 &lt;&lt; 63, and has
  /// fetch and decrement bounded (FC 28) compare with the doubleword above.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC64] LDAT updates a doubleword atomically``() =
    let a, b, top = 0xfffffff0fffffff0UL, 0x700000003UL, 1UL <<< 63
    let low1 = 0x8000000000000001UL
    (* ldat r10, r6, FC *)
    expectAtomic
      [ ppc64 ]
      0x7d4604ccu
      [ 0u, 3UL, blockA, a, 0xfffffff0fffffff3UL
        0u, low1, blockA, a, 0x7ffffff0fffffff1UL
        1u, b, blockB, b, 0UL
        2u, 3UL, blockA, a, 0xfffffff0fffffff3UL
        3u, low1, blockA, a, 0x8000000000000000UL
        4u, 3UL, blockA, a, a
        5u, 3UL, blockA, a, 3UL
        6u, low1, blockA, a, low1
        7u, low1, blockA, a, low1
        8u, 3UL, blockA, a, 3UL
        16u, 3UL, blockA, a, 0x99UL
        16u, b, blockB, b, b
        24u, 3UL, blockA, a, 0xfffffff0fffffff1UL
        24u, b, blockB, top, b
        25u, b, blockB, b, 0x700000004UL
        25u, 3UL, blockA, top, a
        28u, 3UL, blockA, a, 0xfffffff0ffffffefUL
        28u, b, blockB, b, 0x700000002UL ]
    expectAtomic
      [ ppc64le ]
      0x7d4604ccu
      [ 0u, 3UL, blockA, 0xf0fffffff0ffffffUL, 0x020000f1fffffff0UL ]

  /// <summary>
  /// stwat applies the function code to the word at (rA) and r11's low word
  /// (Book II 4.5.2, Figure 4); store twin (FC 24) stores it to both words
  /// where they are equal. Values from qemu-ppc64 -cpu power10 (specs amo,
  /// amole), except the signed maximum and minimum (FC 5, 7), which QEMU
  /// 8.2.2 compares unsigned (deviations/ppc64/lwat.c).
  /// </summary>
  [<TestMethod>]
  member _.``[PPC64] STWAT updates a word atomically``() =
    let mark, b3 = 0x1111111111111111UL, 0x700000003UL
    (* stwat r11, r6, FC *)
    expectAtomic
      [ ppc64 ]
      0x7d66058cu
      [ 0u, 3UL, blockA, mark, 0xfffffff3fffffff0UL
        1u, b3, blockB, mark, 0x0000000400000003UL
        3u, 3UL, blockA, mark, 0x00000000fffffff0UL
        4u, 3UL, blockA, mark, 0xfffffff0fffffff0UL
        5u, 3UL, blockA, mark, 0x00000003fffffff0UL
        6u, 3UL, blockA, mark, 0x00000003fffffff0UL
        7u, 3UL, blockA, mark, 0xfffffff0fffffff0UL
        24u, 3UL, blockA, mark, 0x0000000300000003UL
        24u, b3, blockB, mark, 0x0000000700000003UL ]
    expectAtomic
      [ ppc64le ]
      0x7d66058cu
      [ 0u, 3UL, blockA, mark, 0x020000f1fffffff0UL ]

  /// <summary>
  /// stdat applies the function code to the doubleword at (rA) and r11
  /// (Book II 4.5.2, Figure 4); store twin (FC 24) stores nothing where the
  /// two doublewords differ. Values from qemu-ppc64 -cpu power10 (specs amo,
  /// amole).
  /// </summary>
  [<TestMethod>]
  member _.``[PPC64] STDAT updates a doubleword atomically``() =
    let mark, low1 = 0x1111111111111111UL, 0x8000000000000001UL
    (* stdat r11, r6, FC *)
    expectAtomic
      [ ppc64 ]
      0x7d6605ccu
      [ 0u, 3UL, blockA, mark, 0xfffffff0fffffff3UL
        1u, 0x700000003UL, blockB, mark, 0UL
        3u, low1, blockA, mark, 0x8000000000000000UL
        5u, 3UL, blockA, mark, 3UL
        7u, low1, blockA, mark, low1
        24u, 3UL, blockA, mark, 0xfffffff0fffffff0UL ]
    expectAtomic
      [ ppc64le ]
      0x7d6605ccu
      [ 0u, 3UL, blockA, mark, 0x020000f1fffffff0UL ]

  /// <summary>
  /// An atomic memory operation with a function code Figure 3 or 4 does not
  /// list invokes the data storage error handler, and one whose address is
  /// not a multiple of its size, or whose operands leave the aligned 32-byte
  /// block, the alignment error handler (Book II 4.5). QEMU 8.2.2 raises
  /// SIGSEGV and SIGBUS for the first two (spec amo) but runs the operations
  /// that leave the block (deviations/ppc64/lwat.c).
  /// </summary>
  [<TestMethod>]
  member _.``[PPC64] The atomic memory operations fault``() =
    let words = [ 0x7d46048cu; 0x7d4604ccu; 0x7d66058cu; 0x7d6605ccu ]
    for isa in ppc64s do
      for word in words do
        let bad = $"{word ||| (9u <<< 11):x8}"
        let at = 0x20200088UL
        Assert.IsTrue(raisesAt isa bad at "Exception(ProtectionFault)", bad)
        let hex = $"{word:x8}"
        let odd = 0x2020008aUL
        Assert.IsTrue(raisesAt isa hex odd "Exception(MisalignedAccess)", hex)
      (* ldat r10, r6, 24 at 0x20200098; lwat r10, r6, 28 at 0x20200080 *)
      for hex, at in [ "7d46c4cc", 0x20200098UL; "7d46e48c", 0x20200080UL ] do
        Assert.IsTrue(raisesAt isa hex at "Exception(MisalignedAccess)", hex)

  /// <summary>
  /// copy loads a block into the copy buffer of the copy-paste facility,
  /// which is optional for every compliancy subset; where it is not
  /// included, running copy invokes the hypervisor emulation assistance --
  /// an illegal instruction to a program. This model leaves it out, as QEMU
  /// 8.2.2 does (it raises SIGILL; spec copypaste).
  /// </summary>
  [<TestMethod>]
  member _.``[PPC64] COPY is an illegal instruction``() =
    (* copy r6, r7 *)
    for isa in ppc64s do
      let lifted = effects isa "7c263e0c"
      CollectionAssert.AreEqual([| UndefinedInstruction |], lifted)

  /// <summary>
  /// paste, like copy, belongs to the copy-paste facility this model leaves
  /// out, as QEMU 8.2.2 does (SIGILL; spec copypaste).
  /// </summary>
  [<TestMethod>]
  member _.``[PPC64] PASTE is an illegal instruction``() =
    (* paste r6, r7, 1 *)
    for isa in ppc64s do
      let lifted = effects isa "7c263f0c"
      CollectionAssert.AreEqual([| UndefinedInstruction |], lifted)

  /// <summary>
  /// paste., like copy, belongs to the copy-paste facility this model leaves
  /// out, as QEMU 8.2.2 does (SIGILL; spec copypaste).
  /// </summary>
  [<TestMethod>]
  member _.``[PPC64] PASTE. is an illegal instruction``() =
    (* paste. r6, r7, 1 *)
    for isa in ppc64s do
      let lifted = effects isa "7c263f0d"
      CollectionAssert.AreEqual([| UndefinedInstruction |], lifted)

  /// <summary>
  /// cpabort clears the state of a copy-paste sequence; with no copy buffer
  /// there is none, and it changes nothing, as QEMU's power10 runs it (spec
  /// copypaste).
  /// </summary>
  [<TestMethod>]
  member _.``[PPC64] CPABORT changes nothing``() =
    (* cpabort *)
    for isa in ppc64s do
      expect 0UL (uint64 (writes isa "7c00068c").Length) (nameOf isa)

  /// <summary>
  /// wait suspends the processor until an exception, the loss of the
  /// reservation (WC = 1) or a short time (WC = 2); to a program it is a
  /// delay, as pause is on other architectures. The reference cannot run
  /// it: QEMU's user mode would stop there.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC64] WAIT is a delay``() =
    (* wait 0,0; wait 1,0; wait 2,0 *)
    for isa in ppc64s do
      for hex in [ "7c00003c"; "7c20003c"; "7c40003c" ] do
        CollectionAssert.AreEqual([| Delay |], effects isa hex, hex)

  /// <summary>
  /// scv calls the system, as sc does; the system's convention for scv
  /// differs (Linux returns an error as a negative r3 rather than in
  /// CR0[SO]), which is the emulator's to keep. QEMU 8.2.2 refuses scv in
  /// user mode (SIGILL; spec copypaste, deviations/ppc64/scv.c).
  /// </summary>
  [<TestMethod>]
  member _.``[PPC64] SCV calls the system``() =
    (* scv 0 *)
    for isa in ppc64s do
      CollectionAssert.AreEqual([| SysCall |], effects isa "44000001")

/// <summary>
/// Lane F's lifting tests: the binary floating-point instructions added
/// after the first PowerPC, the floating-point register pair accesses, the
/// FPSCR, and the Decimal Floating-Point facility. Every expected value is
/// QEMU's (optest-powerpc/oracle), unless a test says the manual and QEMU
/// part, in which case it is the manual's.
/// </summary>
[<TestClass>]
type FloatLifterTests() =
  /// 32-bit PowerPC, big-endian.
  let ppc32 = ISA(Architecture.PPC, Endian.Big, WordSize.Bit32)

  /// 64-bit PowerPC, big-endian.
  let ppc64 = ISA(Architecture.PPC, Endian.Big, WordSize.Bit64)

  /// 64-bit PowerPC, little-endian.
  let ppc64le = ISA(Architecture.PPC, Endian.Little, WordSize.Bit64)

  /// The statements one word lifts to on the processor an ISA names. The hex
  /// is the word as the Power ISA draws it, most significant byte first.
  let lifted (isa: ISA) (hex: string) =
    let word = ByteArray.ofHexString hex
    let bytes = if isa.Endian = Endian.Big then word else Array.rev word
    let reader = BinReader.Init isa.Endian
    let parser = Parser(isa.WordSize, reader) :> IInstructionParsable
    let regs = RegisterFactory isa :> IRegisterFactory
    let builder = ILowUIRBuilder.Default(isa, regs, LowUIRStream())
    (parser.Parse(bytes, 0UL)).Translate builder

  /// The variable of a register on the processor an ISA names.
  let var (isa: ISA) r =
    (RegisterFactory isa :> IRegisterFactory).GetRegVar(Register.toRegID r)

  /// The registers given values, each value at the width of its register.
  let inputsOf isa given =
    given
    |> List.map (fun (r, v: uint64) ->
      let x = var isa r
      x, BitVector(v, Expr.typeOf x))

  /// What each register holds after one word ran, over the registers given
  /// values and the bytes of memory given, and every byte of memory given or
  /// written after the run.
  let exec isa hex given memory =
    let outcome = IRRunner.exec (lifted isa hex) (inputsOf isa given) memory
    (fun r -> (outcome.Read(var isa r)).ToUInt64()), outcome.Memory

  /// What each register holds after one word ran, with no memory at all.
  let run isa hex given = exec isa hex given [] |> fst

  /// Asserts that a run left the expected value, naming the case it ran.
  let expect (expected: uint64) (actual: uint64) (case: string) =
    Assert.AreEqual(box expected, box actual, case)

  /// The processor an ISA names, for a message.
  let nameOf (isa: ISA) = $"{isa.WordSize} {isa.Endian}"

  /// The four bits of a CR field, as the Power ISA draws one: bit 0 (LT or
  /// FL) the most significant.
  let field after (b0, b1, b2, b3) =
    (after b0 <<< 3) ||| (after b1 <<< 2) ||| (after b2 <<< 1) ||| after b3

  /// CR1 as its four bit registers.
  let cr1 = CR1_0, CR1_1, CR1_2, CR1_3

  /// CR2 as its four bit registers.
  let cr2 = CR2_0, CR2_1, CR2_2, CR2_3

  /// The eight bytes of a doubleword as a big-endian processor stores it.
  let bigBytes (v: uint64) = Array.init 8 (fun i -> byte (v >>> (56 - 8 * i)))

  /// A doubleword with its bytes in the other order.
  let swap (v: uint64) =
    BitConverter.ToUInt64(Array.rev (BitConverter.GetBytes v), 0)

  /// The doubles the tests use most, by their bits.
  let one = 0x3ff0000000000000UL

  let oneHalf = 0x3ff8000000000000UL

  let tenth = 0x3fb999999999999aUL

  let infinity = 0x7ff0000000000000UL

  let minusInfinity = 0xfff0000000000000UL

  let qnan = 0x7ff8000000000000UL

  let maxDouble = 0x7fefffffffffffffUL

  let minusZero = 0x8000000000000000UL

  /// FPSCR[FR]. QEMU leaves it as it was where the manual sets or clears it
  /// (optest-powerpc/lanes/F.md), so the QEMU vectors compare everything
  /// but FR, and FR has tests of its own.
  let fr = 0x40000UL

  /// <summary>
  /// Runs a floating-point word on every target over the values given to the
  /// FPRs the text names after the target, in that order, and FPSCR, and
  /// checks frD and the FPSCR but for FR: one case per QEMU vector, as
  /// (operands, FPSCR before, frD after, FPSCR after).
  /// </summary>
  let checkFP hex dst srcs cases =
    for isa in [ ppc32; ppc64; ppc64le ] do
      for (ops: uint64 list), fpscr, result, after in cases do
        let given = (FPSCR, fpscr) :: List.zip srcs ops
        let out = run isa hex given
        let case = $"{hex} %A{ops} {fpscr:x} {nameOf isa}"
        expect result (out dst) case
        expect (after &&& ~~~fr) (out FPSCR &&& ~~~fr) case

  /// <summary>
  /// Runs a DFP word with its named calls answered from the given table
  /// (name to value), which stands in for BRemu's decimal arithmetic: the
  /// run shows which calls the lifter made with which arguments, and where
  /// their answers went. Gives the registers after the run and the calls
  /// made, each as its name and its arguments' values.
  /// </summary>
  let runDFP isa hex given (answers: (string * BitVector) list) =
    let answer name _ = List.tryFind (fst >> (=) name) answers |> Option.map snd
    let stmts = lifted isa hex
    let o = IRRunner.execAnswering answer stmts (inputsOf isa given) []
    let valuesOf (args: BitVector list) =
      args |> List.map (fun a -> a.ToBigInt())
    let calls = o.Calls |> List.map (fun (n, args) -> n, valuesOf args)
    (fun r -> (o.Read(var isa r)).ToUInt64()), calls

  /// A 128-bit value, its high doubleword first.
  let wide (hi: uint64) (lo: uint64) = (bigint hi <<< 64) + bigint lo

  /// An answer of a named call.
  let answerOf (v: bigint) (t: RegType) = BitVector(v, t)

  /// <summary>
  /// fcpsgn. frD, frA, frB writes frB with the sign of frA and records
  /// FPSCR[FX, FEX, VX, OX] in CR1.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] FCPSGN. copies the sign and records CR1``() =
    (* fcpsgn. f1, f2, f3 *)
    for isa in [ ppc32; ppc64; ppc64le ] do
      for a, b, fpscr, result, field1 in
        [ qnan, one, 0xbff80000UL, one, 0xbUL
          0UL, minusZero, 0x2UL, 0UL, 0UL
          maxDouble, maxDouble, 0x20000702UL, maxDouble, 0x2UL ] do
        let after = run isa "fc221811" [ F2, a; F3, b; FPSCR, fpscr ]
        expect result (after F1) (nameOf isa)
        expect field1 (field after cr1) (nameOf isa)

  /// <summary>
  /// fmrgew frD, frA, frB writes word 0 (the high word) of frA and then word
  /// 0 of frB; fmrgow writes word 1 of each.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] FMRGEW and FMRGOW merge words``() =
    (* fmrgew f1, f2, f3; fmrgow f1, f2, f3 *)
    for isa in [ ppc32; ppc64; ppc64le ] do
      for hex, a, b, result in
        [ "fc221f8c", oneHalf, 0x4002000000000000UL, 0x3ff8000040020000UL
          "fc221f8c", infinity, minusInfinity, 0x7ff00000fff00000UL
          "fc221e8c", one, tenth, 0x9999999aUL
          "fc221e8c", 0x1UL, 0xfffffffffffffUL, 0x1ffffffffUL ] do
        let after = run isa hex [ F2, a; F3, b ]
        expect result (after F1) $"{hex} {nameOf isa}"

  /// <summary>
  /// ftdiv BF, frA, frB sets CR field BF to fl || fg || fe || 0: fl is 1, as
  /// the estimates are the exact reciprocals; fe for a NaN or an infinity in
  /// frA, a zero, NaN or infinity in frB, or exponents a divide cannot take
  /// without special handling; fg for an infinity in frA or a zero, infinity
  /// or denormal in frB.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] FTDIV tests the operands of a divide``() =
    (* ftdiv cr2, f2, f3 *)
    for isa in [ ppc32; ppc64; ppc64le ] do
      for a, b, result in
        [ oneHalf, 0x4002000000000000UL, 0x8UL
          one, tenth, 0x8UL
          0UL, minusZero, 0xeUL
          infinity, minusInfinity, 0xeUL
          qnan, one, 0xaUL
          0x1UL, 0xfffffffffffffUL, 0xeUL
          maxDouble, maxDouble, 0xaUL
          one, 0UL, 0xeUL ] do
        let after = run isa "fd021900" [ F2, a; F3, b ]
        expect result (field after cr2) $"{a:x} {b:x} {nameOf isa}"

  /// <summary>
  /// ftsqrt BF, frB sets CR field BF to fl || fg || fe || 0: fe for a zero, a
  /// NaN, an infinity, a negative value or an exponent at or below -970; fg
  /// for a zero, an infinity or a denormal.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] FTSQRT tests the operand of a square root``() =
    (* ftsqrt cr2, f3 *)
    for isa in [ ppc32; ppc64; ppc64le ] do
      for b, result in
        [ oneHalf, 0x8UL
          0UL, 0xeUL
          infinity, 0xeUL
          qnan, 0xaUL
          0x1UL, 0xeUL
          maxDouble, 0x8UL ] do
        let after = run isa "fd001940" [ F3, b ]
        expect result (field after cr2) $"{b:x} {nameOf isa}"

  /// <summary>
  /// lfdp frTp, DS(rA) and lfdpx frTp, rA, rB load the doubleword at EA into
  /// the even register of the pair and the one at EA + 8 into the odd one,
  /// each in the processor's byte order. QEMU swaps the two in little-endian
  /// mode; the manual's pseudocode does not, and is followed here (see
  /// optest-powerpc/lanes/F.md).
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] LFDP and LFDPX load a register pair``() =
    let lo, hi = 0xff19a056aef92bd2UL, 0x3204aae99af7e745UL
    let memory = [ 0x1008UL, Array.append (bigBytes lo) (bigBytes hi) ]
    (* lfdp f2, 8(r6); lfdpx f2, r6, r7 *)
    for hex in [ "e4460008"; "7c463e2e" ] do
      for isa, even, odd in
        [ ppc32, lo, hi; ppc64, lo, hi; ppc64le, swap lo, swap hi ] do
        let given = [ R6, 0x1000UL; R7, 8UL; F2, 0x4045000000000000UL ]
        let after, _ = exec isa hex given memory
        expect even (after F2) $"{hex} {nameOf isa}"
        expect odd (after F3) $"{hex} {nameOf isa}"

  /// <summary>
  /// stfdp frSp, DS(rA) and stfdpx frSp, rA, rB store the even register of
  /// the pair at EA and the odd one at EA + 8, each in the processor's byte
  /// order.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] STFDP and STFDPX store a register pair``() =
    (* stfdp f2, 8(r6); stfdpx f2, r6, r7 *)
    for hex in [ "f4460008"; "7c463f2e" ] do
      for isa in [ ppc32; ppc64; ppc64le ] do
        let given = [ R6, 0x1000UL; R7, 8UL; F2, oneHalf; F3, 0x5UL ]
        let _, memory = exec isa hex given []
        let written = Array.init 16 (fun i -> memory[0x1008UL + uint64 i])
        let order = if isa.Endian = Endian.Big then id else Array.rev
        let expected =
          Array.append (order (bigBytes oneHalf)) (order (bigBytes 0x5UL))
        CollectionAssert.AreEqual(expected, written, $"{hex} {nameOf isa}")

  /// <summary>
  /// fre frD, frB and frsqrtes frD, frB estimate the reciprocal and the
  /// reciprocal square root; where the exact answer is representable, the
  /// estimate is it.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] FRE and FRSQRTES are exact where the answer is``() =
    (* fre f1, f3; frsqrtes f1, f3 *)
    for isa in [ ppc32; ppc64; ppc64le ] do
      for hex, b, result in
        [ "fc201830", one, one
          "fc201830", 0x4010000000000000UL, 0x3fd0000000000000UL
          "fc201830", infinity, 0UL
          "ec201834", one, one
          "ec201834", 0x4010000000000000UL, 0x3fe0000000000000UL
          "ec201834", infinity, 0UL ] do
        let after = run isa hex [ F3, b ]
        expect result (after F1) $"{hex} {b:x} {nameOf isa}"

  /// <summary>
  /// mffs frD reads the whole 64-bit FPSCR: DRN, in the high word, with the
  /// low word below it.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] MFFS reads both words of the FPSCR``() =
    (* mffs f1 *)
    for isa in [ ppc32; ppc64; ppc64le ] do
      let after = run isa "fc20048e" [ FPSCRH, 5UL; FPSCR, 0x82024003UL ]
      expect 0x582024003UL (after F1) (nameOf isa)

  /// <summary>
  /// mffsce frD reads the whole FPSCR and then clears VE, OE, UE, ZE and XE,
  /// and FEX with them.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] MFFSCE reads the FPSCR and clears the enables``() =
    (* mffsce f1 *)
    for isa in [ ppc32; ppc64; ppc64le ] do
      for fpscr, result in
        [ 0x82024003UL, 0x82024003UL
          0x7f001UL, 0x7f001UL
          0xc20000f9UL, 0x82000001UL ] do
        let after = run isa "fc21048e" [ FPSCR, fpscr ]
        expect fpscr (after F1) $"{fpscr:x} {nameOf isa}"
        expect result (after FPSCR) $"{fpscr:x} {nameOf isa}"

  /// <summary>
  /// mffsl frD reads the control bits (DRN and VE..RN) and the non-sticky
  /// status bits (FR, FI, FPRF) of the FPSCR, every other bit zero.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] MFFSL reads only the control and non-sticky bits``() =
    (* mffsl f1 *)
    for isa in [ ppc32; ppc64; ppc64le ] do
      for drn, fpscr, result in
        [ 0UL, 0x82024003UL, 0x24003UL
          0UL, 0xbff80000UL, 0UL
          0UL, 0x7f001UL, 0x7f001UL
          0UL, 0x20000702UL, 0x2UL
          6UL, 0x20000702UL, 0x600000002UL ] do
        let after = run isa "fc38048e" [ FPSCRH, drn; FPSCR, fpscr ]
        expect result (after F1) $"{fpscr:x} {nameOf isa}"

  /// <summary>
  /// mffscdrn frD, frB reads the control bits and then sets DRN from bits
  /// 29:31 of frB; mffscdrni frD, DRM sets it from the immediate.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] MFFSCDRN and MFFSCDRNI set DRN``() =
    (* mffscdrn f1, f3; mffscdrni f1, 1 *)
    for isa in [ ppc32; ppc64; ppc64le ] do
      for hex, b, fpscr, result, drn in
        [ "fc341c8e", maxDouble, 0x20000702UL, 0x2UL, 7UL
          "fc341c8e", oneHalf, 0x82024003UL, 0x3UL, 0UL
          "fc350c8e", 0UL, 0x82024003UL, 0x3UL, 1UL
          "fc350c8e", 0UL, 0xbff80000UL, 0UL, 1UL ] do
        let after = run isa hex [ F3, b; FPSCR, fpscr ]
        expect result (after F1) $"{hex} {nameOf isa}"
        expect drn (after FPSCRH) $"{hex} {nameOf isa}"
        expect fpscr (after FPSCR) $"{hex} {nameOf isa}"

  /// <summary>
  /// mtfsfi. BF, U writes field BF of the FPSCR's low word, recomputes VX
  /// and FEX, and records CR1; with W = 1 it writes the high word, where
  /// field 7 holds DRN.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] MTFSFI. records CR1 and MTFSFI W sets DRN``() =
    (* mtfsfi. 2, 0; mtfsfi 7, 1, 1 *)
    for isa in [ ppc32; ppc64; ppc64le ] do
      let after = run isa "fd00010d" [ FPSCR, 0xbff80000UL ]
      expect 0xbf080000UL (after FPSCR) (nameOf isa)
      expect 0xbUL (field after cr1) (nameOf isa)
      let after = run isa "ff81110c" [ FPSCRH, 6UL; FPSCR, 0x3UL ]
      expect 1UL (after FPSCRH) (nameOf isa)
      expect 0x3UL (after FPSCR) (nameOf isa)

  /// <summary>
  /// mtfsb1 BT sets FPSCR bit BT + 32 and, as the manual's Special Registers
  /// Altered says, FX where that is an exception bit turning on; VX follows.
  /// QEMU 8.2 leaves FX alone here (see optest-powerpc/lanes/F.md).
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] MTFSB1 sets FX with an exception bit``() =
    (* mtfsb1 9 (VXIDI) *)
    for isa in [ ppc32; ppc64; ppc64le ] do
      for fpscr, result in
        [ 0UL, 0xa0400000UL
          0x7f001UL, 0xa047f001UL
          0x82024003UL, 0xa2424003UL ] do
        let after = run isa "fd20004c" [ FPSCR, fpscr ]
        expect result (after FPSCR) $"{fpscr:x} {nameOf isa}"

  /// <summary>
  /// mtfsf FLM, frB with L = 1 writes the whole FPSCR from frB: DRN from
  /// the high word, the low word with FEX and VX recomputed.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] MTFSF with L writes both words``() =
    (* mtfsf 255, f3, 1, 0; mtfsf 255, f3 *)
    for isa in [ ppc32; ppc64; ppc64le ] do
      let b = 0x0000000582024003UL
      let after = run isa "fffe1d8e" [ F3, b; FPSCR, 0x20000702UL ]
      expect 0x82024003UL (after FPSCR) (nameOf isa)
      expect 5UL (after FPSCRH) (nameOf isa)
      let after = run isa "fdfe1d8e" [ F3, b; FPSCRH, 2UL ]
      expect 0x82024003UL (after FPSCR) (nameOf isa)
      expect 2UL (after FPSCRH) (nameOf isa)

  /// <summary>
  /// mfocrf rD, FXM reads the CR field FXM names into its place in rD; the
  /// rest of rD, which the manual leaves undefined, is zero, as QEMU makes
  /// it.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] MFOCRF reads one CR field``() =
    (* mfocrf r5, 32 *)
    for isa in [ ppc32; ppc64; ppc64le ] do
      for cr2Bits, result in [ 0b0110UL, 0x600000UL; 0b1111UL, 0xf00000UL ] do
        let bit n = (cr2Bits >>> n) &&& 1UL
        let given =
          [ CR2_0, bit 3
            CR2_1, bit 2
            CR2_2, bit 1
            CR2_3, bit 0
            CR0_0, 1UL
            CR7_3, 1UL
            R5, 0xbad0bad0UL ]
        let after = run isa "7cb20026" given
        expect result (after R5) (nameOf isa)

  /// <summary>
  /// fadds rounds the exact sum to single precision once. 1.0 + (2^-24 +
  /// 2^-50) lies above the midpoint between 1.0 and 1.0 + 2^-23, so it rounds
  /// up; converting the operands to single first loses the 2^-50 and rounds
  /// the tie to even, down to 1.0. FR records the rounding up (QEMU leaves FR
  /// as it was).
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] FADDS rounds the exact sum to single once``() =
    (* fadds f1, f2, f3 *)
    checkFP "ec22182a" F1 [ F2; F3 ]
      [ [ one; 0x3e70000004000000UL ], 0UL, 0x3ff0000020000000UL, 0x82024000UL
        [ one; 0x3e70000004000000UL ], 1UL, one, 0x82024001UL ]
    for isa in [ ppc32; ppc64; ppc64le ] do
      let after = run isa "ec22182a" [ F2, one; F3, 0x3e70000004000000UL ]
      expect fr (after FPSCR &&& fr) (nameOf isa)

  /// <summary>
  /// fadds over QEMU's vectors: an exact sum, an inexact one truncated, a
  /// zero, infinities of opposite signs (VXISI, the default QNaN), a QNaN
  /// operand, a sum too small for a single (UX, XX), and one too large for
  /// it in round toward +infinity (OX, +infinity).
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] FADDS sets the FPSCR as QEMU does``() =
    (* fadds f1, f2, f3 *)
    checkFP "ec22182a" F1 [ F2; F3 ]
      [ [ oneHalf; 0x4002000000000000UL ], 0UL, 0x400e000000000000UL, 0x4000UL
        [ one; tenth ], 1UL, 0x3ff1999980000000UL, 0x82024001UL
        [ 0UL; minusZero ], 2UL, 0UL, 0x2002UL
        [ infinity; minusInfinity ], 3UL, qnan, 0xa0811003UL
        [ qnan; one ], 0xbff80000UL, qnan, 0xbff91000UL
        [ 1UL; 0xfffffffffffffUL ], 0x7f001UL, 0UL, 0x8a062001UL
        [ maxDouble; maxDouble ], 0x20000702UL, infinity, 0xb2025702UL
        [ one; 0UL ], 0x82024003UL, one, 0x82004003UL ]

  /// <summary>
  /// fmul, fdiv and fsqrt over QEMU's vectors: VXIMZ is not raised by a
  /// signed zero times a zero; 0/0 raises VXZDZ and infinity over infinity
  /// VXIDI; a divide by zero raises ZX and clears FR and FI; an exact result
  /// clears FI.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] FMUL FDIV FSQRT set the FPSCR as QEMU does``() =
    (* fmul f1, f2, f4; fdiv f1, f2, f3; fsqrt f1, f3 *)
    checkFP "fc220132" F1 [ F2; F4 ]
      [ [ oneHalf; 0x4002000000000000UL ], 0UL, 0x400b000000000000UL, 0x4000UL
        [ 0UL; minusZero ], 2UL, minusZero, 0x12002UL
        [ infinity; minusInfinity ], 3UL, minusInfinity, 0x9003UL
        [ 1UL; 0xfffffffffffffUL ], 0x7f001UL, 0UL, 0x8a062001UL
        [ maxDouble; maxDouble ], 0x20000702UL, infinity, 0xb2025702UL ]
    let third = 0x3fe5555555555555UL
    let tiny = 0x3cb0000000000001UL
    checkFP "fc221824" F1 [ F2; F3 ]
      [ [ oneHalf; 0x4002000000000000UL ], 0UL, third, 0x82024000UL
        [ one; tenth ], 1UL, 0x4023ffffffffffffUL, 0x82024001UL
        [ 0UL; minusZero ], 2UL, qnan, 0xa0211002UL
        [ infinity; minusInfinity ], 3UL, qnan, 0xa0411003UL
        [ 1UL; 0xfffffffffffffUL ], 0x7f001UL, tiny, 0x82064001UL
        [ maxDouble; maxDouble ], 0x20000702UL, one, 0x20004702UL
        [ one; 0UL ], 0x82024003UL, infinity, 0x86005003UL ]
    checkFP "fc20182c" F1 [ F3 ]
      [ [ oneHalf ], 0UL, 0x3ff3988e1409212eUL, 0x82024000UL
        [ 0UL ], 2UL, 0UL, 0x2002UL
        [ infinity ], 3UL, infinity, 0x5003UL
        [ 1UL ], 0x7f001UL, 0x1e60000000000000UL, 0x44001UL
        [ maxDouble ], 0x20000702UL, 0x5ff0000000000000UL, 0xa2024702UL ]

  /// <summary>
  /// fmadd, fmadds and fnmsubs over QEMU's vectors: one rounding of frA x
  /// frC + frB; a QNaN in frA wins over an SNaN in frB; a tiny single
  /// result underflows to zero.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] FMADD FMADDS FNMSUBS set the FPSCR as QEMU does``() =
    (* fmadd f1, f2, f4, f3; fmadds f1, f2, f4, f3; fnmsubs f1, f2, f4, f3 *)
    let snan = 0x7ff4000000000001UL
    let x, y, z = oneHalf, 0x4002000000000000UL, 0xbfe8000000000000UL
    let two, three = 0x4000000000000000UL, 0x4008000000000000UL
    let small, minNormal = 0xfffffffffffffUL, 0x10000000000000UL
    let near = 0x4007333320000000UL
    for hex, sum in
      [ "fc22193a", 0x4008ccccccccccccUL; "ec22193a", 0x4008ccccc0000000UL ] do
      checkFP hex F1 [ F2; F4; F3 ]
        [ [ x; y; z ], 0UL, 0x4005000000000000UL, 0x4000UL
          [ one; tenth; three ], 1UL, sum, 0x82024001UL
          [ infinity; minusInfinity; one ], 3UL, minusInfinity, 0x9003UL
          [ qnan; one; snan ], 0xbff80000UL, qnan, 0xbff91000UL
          [ maxDouble; maxDouble; two ], 0x20000702UL, infinity, 0xb2025702UL ]
    checkFP "ec22193c" F1 [ F2; F4; F3 ]
      [ [ x; y; z ], 0UL, 0xc010800000000000UL, 0x8000UL
        [ one; tenth; three ], 1UL, near, 0x82024001UL
        [ 1UL; small; minNormal ], 0x7f001UL, 0UL, 0x8a062001UL ]

  /// <summary>
  /// fnmsub rounds frA x frC - frB and THEN negates it (manual p. 164), so
  /// toward +infinity the magnitude of a positive product rounds up before
  /// the sign turns: -(max x max - 2) overflows to -infinity, and -(0.1 -
  /// 3) is 2.8999998 rather than 2.9000001. QEMU negates first.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] FNMSUBS negates the rounded result``() =
    (* fnmsubs f1, f2, f4, f3 *)
    let two, three = 0x4000000000000000UL, 0x4008000000000000UL
    let near = 0x4007333320000000UL
    checkFP "ec22193c" F1 [ F2; F4; F3 ]
      [ [ maxDouble; maxDouble; two ], 2UL, minusInfinity, 0x92029002UL
        [ one; tenth; three ], 2UL, near, 0x82024002UL ]

  /// <summary>
  /// frsp and fres over QEMU's vectors, where the manual agrees: frsp of a
  /// denormal underflows to zero, of the largest double overflows; fres of
  /// a denormal overflows to the largest single toward zero. Where the
  /// manual and QEMU part, the manual: fres of +0 is +infinity with ZX
  /// (QEMU answers 1/2), and a result that is a single denormal has the
  /// denormal FPRF (QEMU classes it as a double).
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] FRSP and FRES set the FPSCR``() =
    (* frsp f1, f3; fres f1, f3 *)
    checkFP "fc201818" F1 [ F3 ]
      [ [ oneHalf ], 0UL, oneHalf, 0x4000UL
        [ qnan ], 0xbff80000UL, qnan, 0xbff91000UL
        [ 1UL ], 0x7f001UL, 0UL, 0x8a062001UL
        [ maxDouble ], 0x20000702UL, infinity, 0xb2025702UL ]
    checkFP "ec201830" F1 [ F3 ]
      [ [ oneHalf ], 0UL, 0x3fe5555560000000UL, 0x82024000UL
        [ 0UL ], 2UL, infinity, 0x84005002UL
        [ infinity ], 3UL, 0UL, 0x2003UL
        [ 1UL ], 0x7f001UL, 0x47efffffe0000000UL, 0x92064001UL
        [ maxDouble ], 0x20000702UL, 0x36a0000000000000UL, 0xaa034702UL ]

  /// <summary>
  /// FR says the rounding moved the fraction up: 1 + 3 x 2^-54 rounds up to
  /// nearest and FR is 1, truncates toward zero and FR is 0, and an exact
  /// sum clears it (FR is not sticky). QEMU leaves FR as it was.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] FADD sets FR when it rounds up``() =
    (* fadd f1, f2, f3 *)
    for isa in [ ppc32; ppc64; ppc64le ] do
      for b, fpscr, result, fpscrAfter in
        [ 0x3ca8000000000000UL, 0UL, 0x3ff0000000000001UL, 0x82064000UL
          0x3ca8000000000000UL, 1UL, one, 0x82024001UL
          one, fr, 0x4000000000000000UL, 0x4000UL ] do
        let after = run isa "fc22182a" [ F2, one; F3, b; FPSCR, fpscr ]
        expect result (after F1) $"{b:x} {fpscr:x} {nameOf isa}"
        expect fpscrAfter (after FPSCR) $"{b:x} {fpscr:x} {nameOf isa}"

  /// <summary>
  /// A single-precision result that is a denormal single is classed as one
  /// (FPRF 0b10100), even though the double that holds it is normal: 2^-65
  /// x 2^-65 = 2^-130. QEMU classes it as a double (0b00100).
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] FMULS classes a single denormal as denormal``() =
    (* fmuls f1, f2, f4 *)
    let twoToMinus65 = 0x3be0000000000000UL
    let twoToMinus130 = 0x37d0000000000000UL
    let product = [ twoToMinus65; twoToMinus65 ], 0UL, twoToMinus130, 0x14000UL
    checkFP "ec220132" F1 [ F2; F4 ] [ product ]

  /// <summary>
  /// With ZE set, a divide by zero leaves frD and FPRF as they were, clears
  /// FR and FI, and sets ZX, FX and FEX.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] FDIV by zero with ZE keeps the target``() =
    (* fdiv f1, f2, f3 *)
    for isa in [ ppc32; ppc64; ppc64le ] do
      let given = [ F1, 0x4045000000000000UL; F2, one; FPSCR, 0x60010UL ]
      let after = run isa "fc221824" given
      expect 0x4045000000000000UL (after F1) (nameOf isa)
      expect 0xc4000010UL (after FPSCR) (nameOf isa)

  /// <summary>
  /// dadd frT, frA, frB asks DFPEXC (code 1) for its status and DADD for its
  /// result, both with frA, frB and the control byte: FPSCR[DRN] (5 here) in
  /// bits 2:0 under the enables. The result goes to frT; the status's
  /// exception bits are OR-ed into the FPSCR with FX, its FPRF, FR and FI
  /// replace the FPSCR's.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] DADD calls DADD and DFPEXC with DRN``() =
    let a, b = 0x2238000000000001UL, 0x2238000000000002UL
    let answers =
      [ "DFPEXC", answerOf (bigint 0x02024000UL) 32<rt>
        "DADD", answerOf (bigint 0x2238000000000003UL) 64<rt> ]
    (* dadd f1, f2, f3 *)
    for isa in [ ppc32; ppc64; ppc64le ] do
      let given = [ F2, a; F3, b; FPSCR, 0x3UL; FPSCRH, 5UL ]
      let after, calls = runDFP isa "ec221804" given answers
      let expected =
        [ "DFPEXC", [ 1I; bigint a; bigint b; 5I ]
          "DADD", [ bigint a; bigint b; 5I ] ]
      Assert.AreEqual<(string * bigint list) list>(expected, calls)
      expect 0x2238000000000003UL (after F1) (nameOf isa)
      expect 0x82024003UL (after FPSCR) (nameOf isa)

  /// <summary>
  /// daddq frTp, frAp, frBp passes each pair as one 128-bit value, the even
  /// register over the odd one, and writes the 128-bit result the same way.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] DADDQ passes and writes register pairs``() =
    let answers =
      [ "DFPEXC", answerOf (bigint 0x4000UL) 32<rt>
        "DADDQ", answerOf (wide 0x2208000000000000UL 7UL) 128<rt> ]
    (* daddq f2, f4, f6 *)
    for isa in [ ppc32; ppc64; ppc64le ] do
      let given = [ F4, 1UL; F5, 2UL; F6, 3UL; F7, 4UL; FPSCR, 0x80UL ]
      let after, calls = runDFP isa "fc443004" given answers
      let expected =
        [ "DFPEXC", [ 2I; wide 1UL 2UL; wide 3UL 4UL; (bigint 0x80UL) ]
          "DADDQ", [ wide 1UL 2UL; wide 3UL 4UL; (bigint 0x80UL) ] ]
      Assert.AreEqual<(string * bigint list) list>(expected, calls)
      expect 0x2208000000000000UL (after F2) (nameOf isa)
      expect 7UL (after F3) (nameOf isa)
      expect 0x4080UL (after FPSCR) (nameOf isa)

  /// <summary>
  /// With VE set, an invalid operation the status reports (VXIDI) leaves frT
  /// and FPRF as they were; VX, FX and FEX follow.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] DDIV keeps the target on an enabled invalid``() =
    let answers =
      [ "DFPEXC", answerOf (bigint 0x00411000UL) 32<rt>
        "DDIV", answerOf (bigint 0x7c00000000000000UL) 64<rt> ]
    (* ddiv f1, f2, f3 *)
    for isa in [ ppc32; ppc64; ppc64le ] do
      let given = [ F1, 0x1234UL; FPSCR, 0x80UL ]
      let after, _ = runDFP isa "ec221c44" given answers
      expect 0x1234UL (after F1) (nameOf isa)
      expect 0xe0400080UL (after FPSCR) (nameOf isa)

  /// <summary>
  /// dcmpu BF, frA, frB asks DFPEXC (code 9) alone: bits 15:12 of the status
  /// go into CR field BF and FPSCR[FPCC], leaving C as it was.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] DCMPU writes the status's FPCC into the CR field``() =
    let answers = [ "DFPEXC", answerOf (bigint 0x8000UL) 32<rt> ]
    (* dcmpu cr2, f2, f3 *)
    for isa in [ ppc32; ppc64; ppc64le ] do
      let given = [ F2, 6UL; F3, 7UL; FPSCR, 0x1f000UL; CR2_3, 1UL ]
      let after, calls = runDFP isa "ed021d04" given answers
      let expected = [ "DFPEXC", [ 9I; 6I; 7I; 0I ] ]
      Assert.AreEqual<(string * bigint list) list>(expected, calls)
      expect 0x8UL (field after cr2) (nameOf isa)
      expect 0x18000UL (after FPSCR) (nameOf isa)

  /// <summary>
  /// The rounding mode in the control byte: drintx with R = 1 reads RMC in
  /// the secondary encoding (RMC 2 is away from zero, 6), drintn with R = 0
  /// in the primary one (RMC 1 is toward zero, 1), and dqua's RMC 3 defers
  /// to DRN.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] DRINTX DRINTN DQUA take the mode RMC names``() =
    let answers =
      [ "DFPEXC", answerOf 0I 32<rt>
        "DRINTX", answerOf 1I 64<rt>
        "DRINTN", answerOf 1I 64<rt>
        "DQUA", answerOf 1I 64<rt> ]
    (* drintx 1, f1, f3, 2; drintn 0, f1, f3, 1; dqua f1, f2, f3, 3 *)
    for isa in [ ppc32; ppc64; ppc64le ] do
      for hex, call, code, ctl in
        [ "ec211cc6", "DRINTX", 29I, 6I
          "ec201bc6", "DRINTN", 31I, 1I
          "ec221e06", "DQUA", 25I, 4I ] do
        let given = [ F2, 2UL; F3, 3UL; FPSCRH, 4UL ]
        let _, calls = runDFP isa hex given answers
        let args = if call = "DQUA" then [ 2I; 3I; ctl ] else [ 3I; ctl ]
        let expected = [ "DFPEXC", code :: args; call, args ]
        Assert.AreEqual<(string * bigint list) list>(expected, calls, hex)

  /// <summary>
  /// dquai TE, frT, frB, RMC passes TE as a byte, sign and all: 3, and -16
  /// as 0xf0.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] DQUAI passes TE as a signed byte``() =
    let answers =
      [ "DFPEXC", answerOf 0I 32<rt>; "DQUAI", answerOf 1I 64<rt> ]
    (* dquai 3, f1, f3, 1; dquai -16, f1, f3, 1 *)
    for isa in [ ppc32; ppc64; ppc64le ] do
      for hex, te in [ "ec231a86", 3I; "ec301a86", (bigint 0xf0UL) ] do
        let _, calls = runDFP isa hex [ F3, 9UL ] answers
        let expected =
          [ "DFPEXC", [ 23I; te; 9I; 1I ]
            "DQUAI", [ te; 9I; 1I ] ]
        Assert.AreEqual<(string * bigint list) list>(expected, calls, hex)

  /// <summary>
  /// The conversions read and write what their forms name: dctdp the DFP
  /// Short in frB's low word, dcffixqq a VR into a pair, dctfixqq a pair into
  /// a VR -- whose FPRF is undefined and so is not taken from the status.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] DFP conversions read and write their forms``() =
    let answers =
      [ "DFPEXC", answerOf (bigint 0x0203f000UL) 32<rt>
        "DCTDP", answerOf 5I 64<rt>
        "DCFFIXQQ", answerOf (wide 8UL 9UL) 128<rt>
        "DCTFIXQQ", answerOf (wide 10UL 11UL) 128<rt> ]
    (* dctdp f1, f3; dcffixqq f2, v3; dctfixqq v1, f6 *)
    for isa in [ ppc32; ppc64; ppc64le ] do
      let given =
        [ F3, 0x1122334455667788UL; V3A, 1UL; V3B, 2UL; F6, 3UL; F7, 4UL ]
      let after, calls = runDFP isa "ec201a04" given answers
      let short = bigint 0x55667788UL
      let expected = [ "DFPEXC", [ 33I; short; 0I ]; "DCTDP", [ short; 0I ] ]
      Assert.AreEqual<(string * bigint list) list>(expected, calls)
      expect 5UL (after F1) (nameOf isa)
      let after, calls = runDFP isa "fc401fc4" given answers
      let vector = wide 1UL 2UL
      let expected =
        [ "DFPEXC", [ 39I; vector; 0I ]; "DCFFIXQQ", [ vector; 0I ] ]
      Assert.AreEqual<(string * bigint list) list>(expected, calls)
      expect 8UL (after F2) (nameOf isa)
      expect 9UL (after F3) (nameOf isa)
      let after, _ = runDFP isa "fc2137c4" given answers
      expect 10UL (after V1A) (nameOf isa)
      expect 11UL (after V1B) (nameOf isa)
      expect 0x82020000UL (after FPSCR) (nameOf isa)

  /// <summary>
  /// The format instructions alter no FPSCR bit and round nothing: dxex,
  /// ddedpd and dscli make only their result call, without the control byte;
  /// dxex. records CR1 from the FPSCR as it was.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] DXEX DDEDPD DSCLI make only their result call``() =
    let answers =
      [ "DXEX", answerOf 398I 64<rt>
        "DDEDPD", answerOf (bigint 0x123UL) 64<rt>
        "DSCLI", answerOf (bigint 0x40UL) 64<rt> ]
    (* dxex. f1, f3; ddedpd 0, f1, f3; dscli f1, f2, 5 *)
    for isa in [ ppc32; ppc64; ppc64le ] do
      for hex, call, args, result in
        [ "ec201ac5", "DXEX", [ 3I ], 398UL
          "ec201a84", "DDEDPD", [ 0I; 3I ], 0x123UL
          "ec221484", "DSCLI", [ 2I; 5I ], 0x40UL ] do
        let given = [ F2, 2UL; F3, 3UL; FPSCR, 0xa0000000UL ]
        let after, calls = runDFP isa hex given answers
        Assert.AreEqual<(string * bigint list) list>([ call, args ], calls, hex)
        expect result (after F1) hex
        expect 0xa0000000UL (after FPSCR) hex
      let after, _ = runDFP isa "ec201ac5" [ FPSCR, 0xa0000000UL ] answers
      expect 0xaUL (field after cr1) (nameOf isa)

  /// <summary>
  /// The tests pass what they test against: dtstsfi its UIM as a byte,
  /// dtstsf the significance in frA as it is, dtstdc its DCM as a byte.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] DTSTSFI DTSTSF DTSTDC pass their operands``() =
    let answers = [ "DFPEXC", answerOf (bigint 0x2000UL) 32<rt> ]
    (* dtstsfi cr2, 1, f3; dtstsf cr2, f2, f3; dtstdc cr2, f2, 1 *)
    for isa in [ ppc32; ppc64; ppc64le ] do
      for hex, args in
        [ "ed011d46", [ 21I; 1I; 3I; 0I ]
          "ed021d44", [ 19I; 2I; 3I; 0I ]
          "ed020584", [ 13I; 2I; 1I; 0I ] ] do
        let after, calls = runDFP isa hex [ F2, 2UL; F3, 3UL ] answers
        let expected = [ "DFPEXC", args ]
        Assert.AreEqual<(string * bigint list) list>(expected, calls, hex)
        expect 0x2UL (field after cr2) hex

  /// <summary>
  /// fcfids converts the doubleword integer in frB straight to a single,
  /// rounding once, sets FI and XX where that lost anything, and FPRF to the
  /// result's class, which QEMU leaves as it was. 2^62 + 2^38 + 1 rounds to
  /// nearest up past the tie a double would have left at 2^62 + 2^38.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] FCFIDS rounds once and sets FPRF``() =
    (* fcfids f1, f3 *)
    let tie = 0x4000004000000001UL
    checkFP "ec201e9c" F1 [ F3 ]
      [ [ oneHalf ], 0UL, 0x43cffc0000000000UL, 0x4000UL
        [ one ], 1UL, 0x43cff80000000000UL, 0x4001UL
        [ 0UL ], 2UL, 0UL, 0x2002UL
        [ 1UL ], 0x7f001UL, one, 0x4001UL
        [ maxDouble ], 0x20000702UL, 0x43dffc0000000000UL, 0xa2024702UL
        [ tie ], 0UL, 0x43d0000020000000UL, 0x82024000UL ]

  /// <summary>
  /// fctiw, fctiwz and fctidu: the integer, saturated where frB has none the
  /// width holds (VXCVI, and VXSNAN as well for an SNaN), FI and XX where a
  /// fraction was lost, FR where the integer is the farther from zero. FPRF
  /// is undefined (QEMU sets it to the QNaN class on VXCVI) and is not
  /// compared. FX is set only where an exception bit turns on, so a VXCVI
  /// already set leaves it (QEMU sets FX on every exception).
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] FCTIW FCTIWZ FCTIDU set the FPSCR``() =
    (* fctiw f1, f3; fctiwz f1, f3; fctidu f1, f3 *)
    let ignore = fr ||| 0x1f000UL
    let check hex cases =
      for isa in [ ppc32; ppc64; ppc64le ] do
        for b, fpscr, result, after in cases do
          let out = run isa hex [ F3, b; FPSCR, fpscr ]
          let case = $"{hex} {b:x} {fpscr:x} {nameOf isa}"
          expect result (out F1 &&& 0xffffffffUL) case
          expect (after &&& ~~~ignore) (out FPSCR &&& ~~~ignore) case
    check "fc20181c"
      [ oneHalf, 0UL, 2UL, 0x82020000UL
        one, 1UL, 1UL, 1UL
        infinity, 3UL, 0x7fffffffUL, 0xa0011103UL
        qnan, 0xbff80000UL, 0x80000000UL, 0xbff91100UL
        1UL, 0x7f001UL, 0UL, 0x8207f001UL
        maxDouble, 0x20000702UL, 0x7fffffffUL, 0x20000702UL ]
    check "fc20181e" [ oneHalf, 0UL, 1UL, 0x82020000UL ]
    check "fc201f5c"
      [ oneHalf, 0UL, 2UL, 0x82020000UL
        qnan, 0xbff80000UL, 0UL, 0xbff91100UL ]
    for isa in [ ppc32; ppc64; ppc64le ] do
      let out = run isa "fc20181c" [ F3, oneHalf ]
      expect fr (out FPSCR &&& fr) (nameOf isa)

  /// <summary>
  /// frin rounds to the nearest integral value, a tie away from zero, and
  /// sets FR and FI to 0 and FPRF to the result's class.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] FRIN sets FPRF and clears FR and FI``() =
    (* frin f1, f3 *)
    checkFP "fc201b10" F1 [ F3 ]
      [ [ oneHalf ], 0UL, 0x4000000000000000UL, 0x4000UL
        [ 0UL ], 2UL, 0UL, 0x2002UL
        [ infinity ], 3UL, infinity, 0x5003UL
        [ qnan ], 0xbff80000UL, qnan, 0xbff91000UL
        [ 1UL ], 0x7f001UL, 0UL, 0x2001UL
        [ maxDouble ], 0x20000702UL, maxDouble, 0x20004702UL ]
    for isa in [ ppc32; ppc64; ppc64le ] do
      let out = run isa "fc201b10" [ F3, 1UL; FPSCR, 0x7f001UL ]
      expect 0x2001UL (out FPSCR) (nameOf isa)

  /// <summary>
  /// fcmpo BF, frA, frB sets CR field BF and FPSCR[FPCC] to FL, FG, FE or
  /// FU, leaving C as it was (QEMU sets C on an unordered compare); a NaN
  /// raises VXVC, which sets FX where it turns on, and VX.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] FCMPO records the comparison and VXVC``() =
    (* fcmpo cr2, f2, f3 *)
    for isa in [ ppc32; ppc64; ppc64le ] do
      for a, b, fpscr, crField, after in
        [ oneHalf, 0x4002000000000000UL, 0UL, 0x8UL, 0x8000UL
          one, tenth, 1UL, 0x4UL, 0x4001UL
          0UL, minusZero, 2UL, 0x2UL, 0x2002UL
          qnan, one, 0xbff80000UL, 0x1UL, 0xbff81000UL
          qnan, one, 0UL, 0x1UL, 0xa0081000UL ] do
        let out = run isa "fd021840" [ F2, a; F3, b; FPSCR, fpscr ]
        let case = $"{a:x} {b:x} {fpscr:x} {nameOf isa}"
        expect crField (field out cr2) case
        expect after (out FPSCR) case

/// What lane E's lifting tests share: a processor named by the categories it
/// has, and running what a word lifts to on one over registers and memory.
[<AutoOpen>]
module private LaneEShortcut =
  /// A PowerPC ISA of the given byte order and word size whose flags name
  /// the given categories.
  let isaOf endian wordSize (category: Category) =
    ISA(Architecture.PPC, endian, wordSize, int category)

  /// The statements one word at an address lifts to on the processor an ISA
  /// names. The hex is the word as the Power ISA draws it, most significant
  /// byte first.
  let liftedAt (isa: ISA) (address: uint64) (hex: string) =
    let word = ByteArray.ofHexString hex
    let bytes = if isa.Endian = Endian.Big then word else Array.rev word
    let reader = BinReader.Init isa.Endian
    let parser = Parser(isa, reader) :> IInstructionParsable
    let regs = RegisterFactory isa :> IRegisterFactory
    let builder = ILowUIRBuilder.Default(isa, regs, LowUIRStream())
    (parser.Parse(bytes, address)).Translate builder

  /// The statements one word lifts to when it is at address 0.
  let lifted isa hex = liftedAt isa 0UL hex

  /// The variable of a register on the processor an ISA names.
  let var (isa: ISA) r =
    (RegisterFactory isa :> IRegisterFactory).GetRegVar(Register.toRegID r)

  /// The registers given values, each value at the width of its register.
  let inputsOf isa given =
    given
    |> List.map (fun (r, v: uint64) ->
      let x = var isa r
      x, BitVector(v, Expr.typeOf x))

  /// What each register holds after the word at an address ran on the
  /// processor an ISA names, over the registers given values and zero
  /// everywhere else.
  let runAt isa address hex given =
    let read = IRRunner.run (liftedAt isa address hex) (inputsOf isa given)
    fun r -> (read (var isa r)).ToUInt64()

  /// The same for a word at address 0.
  let run isa hex given = runAt isa 0UL hex given

  /// What run gives, over the bytes of memory given as well, and every byte of
  /// memory given or written after the run.
  let exec isa hex given memory =
    let outcome = IRRunner.exec (lifted isa hex) (inputsOf isa given) memory
    (fun r -> (outcome.Read(var isa r)).ToUInt64()), outcome.Memory

  /// CR0 as the Power ISA draws a CR field: LT, GT, EQ and SO from the most
  /// significant bit down.
  let cr0 after =
    (after CR0_0 <<< 3) ||| (after CR0_1 <<< 2) ||| (after CR0_2 <<< 1)
    ||| after CR0_3

  /// Every processor, with the server reading of every encoding: 32-bit
  /// big-endian, and 64-bit big- and little-endian.
  let everyProcessor =
    [ isaOf Endian.Big WordSize.Bit32
      isaOf Endian.Big WordSize.Bit64
      isaOf Endian.Little WordSize.Bit64 ]
    |> List.map (fun isaOn -> isaOn Category.Server)

  /// The same processors with the embedded environment, which reads the word a
  /// server processor reads as eieio as mbar.
  let embeddedProcessors =
    [ isaOf Endian.Big WordSize.Bit32
      isaOf Endian.Big WordSize.Bit64
      isaOf Endian.Little WordSize.Bit64 ]
    |> List.map (fun isaOn -> isaOn Category.Embedded)

/// <summary>
/// Lane E's lifting tests: the instructions of the Power ISA 2.07B
/// categories that 3.1 dropped. Every expected value is QEMU's
/// (optest-powerpc/oracle), unless a test says the manual and QEMU part, or
/// that QEMU does not run the instruction, in which case it is the manual's.
/// </summary>
[<TestClass>]
type LegacyLifterTests() =
  /// The processors a legacy multiply runs on: the 440's own, 32-bit
  /// big-endian, and the 64-bit ones, for which the manual defines the
  /// instructions as well, leaving the high word of rT undefined.
  let multiplyTargets =
    [ isaOf Endian.Big WordSize.Bit32
      isaOf Endian.Big WordSize.Bit64
      isaOf Endian.Little WordSize.Bit64 ]
    |> List.map (fun isaOn -> isaOn Category.LegacyIntegerMultiplyAccumulate)

  /// The operand sets every legacy multiply runs over: rT, rA, rB and XER.
  /// They are the oracle's seeds: small products; sums past the signed
  /// maximum and below the signed minimum; a sum past the unsigned maximum;
  /// SO already set; SO and OV already set with a product of two -2^15; OV
  /// already set alone.
  let multiplySeeds =
    [ 0x10UL, 0x30002UL, 0x50007UL, 0x0UL
      0x7ffffff0UL, 0x7fff7fffUL, 0x7fff7fffUL, 0x0UL
      0x80000010UL, 0x80008000UL, 0x7fff7fffUL, 0x0UL
      0xfffffff0UL, 0xffffffffUL, 0xffffffffUL, 0x0UL
      0x12345678UL, 0x80000001UL, 0x1ffffUL, 0x80000000UL
      0x7fffffffUL, 0x8000UL, 0x80000000UL, 0xc0000000UL
      0xdeadbeefUL, 0xffff0001UL, 0x1ffffUL, 0x40000000UL ]

  /// Runs a legacy multiply, rT r5, rA r6, rB r7, over each operand set on
  /// every target, CR0 starting clear, and asserts what each outcome says:
  /// the low word of rT, XER, and CR0. The high word of rT is not asserted:
  /// the manual leaves it undefined.
  let checkMultiply hex outcomes =
    for isa in multiplyTargets do
      for (rt, ra, rb, xer), (word, xerAfter, field) in
        List.zip multiplySeeds outcomes do
        let after = run isa hex [ R5, rt; R6, ra; R7, rb; XER, xer ]
        let case = $"{hex} {rt:x} {ra:x} {rb:x} {xer:x} {isa}"
        Assert.AreEqual(box word, box (after R5 &&& 0xffffffffUL), case)
        Assert.AreEqual(box xerAfter, box (after XER), case)
        Assert.AreEqual(box field, box (cr0 after), case)

  /// The processors dlmzb runs on: the same, with the Legacy Move Assist
  /// category, which a server processor reads the word of dlmzb without.
  let moveAssistTargets =
    [ isaOf Endian.Big WordSize.Bit32
      isaOf Endian.Big WordSize.Bit64
      isaOf Endian.Little WordSize.Bit64 ]
    |> List.map (fun isaOn -> isaOn Category.LegacyMoveAssist)

  /// The operand sets every dlmzb runs over: rS, rB and XER. They are the
  /// oracle's seeds: no null byte; a null as the first, third and fourth byte
  /// of rS and as the second, third and fourth byte of rB; every byte null;
  /// the byte count of XER already set; the first byte of each word null.
  let dlmzbSeeds =
    [ 0x11223344UL, 0x55667788UL, 0x0UL
      0x112233UL, 0x44556677UL, 0xe0000000UL
      0x11220033UL, 0x44556677UL, 0x20000000UL
      0x11223300UL, 0x44556677UL, 0x80000000UL
      0x11223344UL, 0x55006677UL, 0x40000000UL
      0x11223344UL, 0x55660077UL, 0x0UL
      0x11223344UL, 0x55667700UL, 0x20000000UL
      0x0UL, 0x0UL, 0xa0000000UL
      0x11223344UL, 0x55667788UL, 0xe000007fUL
      0xffUL, 0xff000000UL, 0xfff3ffffUL ]

  /// Runs a dlmzb, rA r5, rS r6, rB r7, over each operand set on every
  /// target, CR starting clear, and asserts what each outcome says: rA, XER and
  /// CR0. On a 64-bit processor the high words of rS and rB hold values the
  /// manual says are not read.
  let checkDlmzb hex outcomes =
    for isa in moveAssistTargets do
      let high =
        if isa.WordSize = WordSize.Bit64 then 0xdeadbeef00000000UL else 0UL
      for (rs, rb, xer), (ra, xerAfter, field) in
        List.zip dlmzbSeeds outcomes do
        let after = run isa hex [ R6, high ||| rs; R7, high ||| rb; XER, xer ]
        let case = $"{hex} {rs:x} {rb:x} {xer:x} {isa}"
        Assert.AreEqual(box ra, box (after R5), case)
        Assert.AreEqual(box xerAfter, box (after XER), case)
        Assert.AreEqual(box field, box (cr0 after), case)

  /// <summary>
  /// macchw rT, rA, rB adds the signed product of rA's low halfword and rB's
  /// high one to rT, the result wrapping at 32 bits. qemu-ppc -cpu 440epx
  /// (8.2.2) never writes rT for this form (deviations/ppc440/lma_qemu.c); the
  /// expected values follow the manual's pseudocode.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] MACCHW accumulates modulo 2^32``() =
    (* macchw r5, r6, r7 *)
    checkMultiply "10a63958"
      [ 0x1aUL, 0x0UL, 0x0UL
        0xbffefff1UL, 0x0UL, 0x0UL
        0x40008010UL, 0x0UL, 0x0UL
        0xfffffff1UL, 0x0UL, 0x0UL
        0x12345679UL, 0x80000000UL, 0x0UL
        0xbfffffffUL, 0xc0000000UL, 0x0UL
        0xdeadbef0UL, 0x40000000UL, 0x0UL ]

  /// <summary>
  /// macchw. rT, rA, rB adds the signed product of rA's low halfword and rB's
  /// high one to rT, the result wrapping at 32 bits; CR0 compares the word
  /// written with zero. qemu-ppc -cpu 440epx (8.2.2) never writes rT for this
  /// form (deviations/ppc440/lma_qemu.c); the expected values follow the
  /// manual's pseudocode.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] MACCHW. accumulates modulo 2^32``() =
    (* macchw. r5, r6, r7 *)
    checkMultiply "10a63959"
      [ 0x1aUL, 0x0UL, 0x4UL
        0xbffefff1UL, 0x0UL, 0x8UL
        0x40008010UL, 0x0UL, 0x4UL
        0xfffffff1UL, 0x0UL, 0x8UL
        0x12345679UL, 0x80000000UL, 0x5UL
        0xbfffffffUL, 0xc0000000UL, 0x9UL
        0xdeadbef0UL, 0x40000000UL, 0x8UL ]

  /// <summary>
  /// macchwo rT, rA, rB adds the signed product of rA's low halfword and rB's
  /// high one to rT, the result wrapping at 32 bits; OV says whether the exact
  /// result fit a word and SO keeps it. qemu-ppc -cpu 440epx (8.2.2) takes a
  /// signed sum that overflows for one that does not, and the other way round
  /// (deviations/ppc440/lma_qemu.c); the expected values follow the manual's
  /// pseudocode.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] MACCHWO accumulates modulo 2^32``() =
    (* macchwo r5, r6, r7 *)
    checkMultiply "10a63d58"
      [ 0x1aUL, 0x0UL, 0x0UL
        0xbffefff1UL, 0xc0000000UL, 0x0UL
        0x40008010UL, 0xc0000000UL, 0x0UL
        0xfffffff1UL, 0x0UL, 0x0UL
        0x12345679UL, 0x80000000UL, 0x0UL
        0xbfffffffUL, 0xc0000000UL, 0x0UL
        0xdeadbef0UL, 0x0UL, 0x0UL ]

  /// <summary>
  /// macchwo. rT, rA, rB adds the signed product of rA's low halfword and rB's
  /// high one to rT, the result wrapping at 32 bits; OV says whether the exact
  /// result fit a word and SO keeps it; CR0 compares the word written with
  /// zero. qemu-ppc -cpu 440epx (8.2.2) takes a signed sum that overflows for
  /// one that does not, and the other way round (deviations/ppc440/lma_qemu.c);
  /// the expected values follow the manual's pseudocode.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] MACCHWO. accumulates modulo 2^32``() =
    (* macchwo. r5, r6, r7 *)
    checkMultiply "10a63d59"
      [ 0x1aUL, 0x0UL, 0x4UL
        0xbffefff1UL, 0xc0000000UL, 0x9UL
        0x40008010UL, 0xc0000000UL, 0x5UL
        0xfffffff1UL, 0x0UL, 0x8UL
        0x12345679UL, 0x80000000UL, 0x5UL
        0xbfffffffUL, 0xc0000000UL, 0x9UL
        0xdeadbef0UL, 0x0UL, 0x8UL ]

  /// <summary>
  /// macchws rT, rA, rB adds the signed product of rA's low halfword and rB's
  /// high one to rT, saturating at the signed limits. qemu-ppc -cpu 440epx
  /// (8.2.2) takes a signed sum that overflows for one that does not, and the
  /// other way round (deviations/ppc440/lma_qemu.c); the expected values follow
  /// the manual's pseudocode.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] MACCHWS accumulates with saturation``() =
    (* macchws r5, r6, r7 *)
    checkMultiply "10a639d8"
      [ 0x1aUL, 0x0UL, 0x0UL
        0x7fffffffUL, 0x0UL, 0x0UL
        0x80000000UL, 0x0UL, 0x0UL
        0xfffffff1UL, 0x0UL, 0x0UL
        0x12345679UL, 0x80000000UL, 0x0UL
        0x7fffffffUL, 0xc0000000UL, 0x0UL
        0xdeadbef0UL, 0x40000000UL, 0x0UL ]

  /// <summary>
