      [ 0xeUL, 0x0UL, 0x0UL
        0x3fff0001UL, 0x0UL, 0x0UL
        0xc0008000UL, 0x0UL, 0x0UL
        0x1UL, 0x0UL, 0x0UL
        0xffffffffUL, 0x80000000UL, 0x0UL
        0x0UL, 0xc0000000UL, 0x0UL
        0xffffffffUL, 0x40000000UL, 0x0UL ]

  /// <summary>
  /// mullhw. rT, rA, rB writes the signed product of the low halfwords of rA
  /// and rB into rT; CR0 compares the word written with zero. The expected
  /// values are what qemu-ppc -cpu 440epx (8.2.2) leaves.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] MULLHW. multiplies two halfwords``() =
    (* mullhw. r5, r6, r7 *)
    checkMultiply "10a63b51"
      [ 0xeUL, 0x0UL, 0x4UL
        0x3fff0001UL, 0x0UL, 0x4UL
        0xc0008000UL, 0x0UL, 0x8UL
        0x1UL, 0x0UL, 0x4UL
        0xffffffffUL, 0x80000000UL, 0x9UL
        0x0UL, 0xc0000000UL, 0x3UL
        0xffffffffUL, 0x40000000UL, 0x8UL ]

  /// <summary>
  /// mullhwu rT, rA, rB writes the unsigned product of the low halfwords of rA
  /// and rB into rT. The expected values are what qemu-ppc -cpu 440epx (8.2.2)
  /// leaves.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] MULLHWU multiplies two halfwords``() =
    (* mullhwu r5, r6, r7 *)
    checkMultiply "10a63b10"
      [ 0xeUL, 0x0UL, 0x0UL
        0x3fff0001UL, 0x0UL, 0x0UL
        0x3fff8000UL, 0x0UL, 0x0UL
        0xfffe0001UL, 0x0UL, 0x0UL
        0xffffUL, 0x80000000UL, 0x0UL
        0x0UL, 0xc0000000UL, 0x0UL
        0xffffUL, 0x40000000UL, 0x0UL ]

  /// <summary>
  /// mullhwu. rT, rA, rB writes the unsigned product of the low halfwords of rA
  /// and rB into rT; CR0 compares the word written with zero. The expected
  /// values are what qemu-ppc -cpu 440epx (8.2.2) leaves.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] MULLHWU. multiplies two halfwords``() =
    (* mullhwu. r5, r6, r7 *)
    checkMultiply "10a63b11"
      [ 0xeUL, 0x0UL, 0x4UL
        0x3fff0001UL, 0x0UL, 0x4UL
        0x3fff8000UL, 0x0UL, 0x4UL
        0xfffe0001UL, 0x0UL, 0x8UL
        0xffffUL, 0x80000000UL, 0x5UL
        0x0UL, 0xc0000000UL, 0x3UL
        0xffffUL, 0x40000000UL, 0x4UL ]

  /// <summary>
  /// dlmzb rA, rS, rB puts the number of the leftmost null byte of the low
  /// words of rS and rB, from 1, or 8 where there is none, into rA and into
  /// the seven low bits of XER. The expected values are what qemu-ppc -cpu
  /// 440epx (8.2.2) leaves.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] DLMZB finds the leftmost null byte``() =
    (* dlmzb r5, r6, r7 *)
    checkDlmzb "7cc5389c"
      [ 0x8UL, 0x8UL, 0x0UL
        0x1UL, 0xe0000001UL, 0x0UL
        0x3UL, 0x20000003UL, 0x0UL
        0x4UL, 0x80000004UL, 0x0UL
        0x6UL, 0x40000006UL, 0x0UL
        0x7UL, 0x7UL, 0x0UL
        0x8UL, 0x20000008UL, 0x0UL
        0x1UL, 0xa0000001UL, 0x0UL
        0x8UL, 0xe0000008UL, 0x0UL
        0x1UL, 0xfff3ff81UL, 0x0UL ]

  /// <summary>
  /// dlmzb. rA, rS, rB does the same and sets CR0: LT where the leftmost null
  /// byte is in rB, GT where it is in rS, EQ where there is none, and SO from
  /// XER. The expected values are what qemu-ppc -cpu 440epx (8.2.2) leaves.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] DLMZB. finds the leftmost null byte``() =
    (* dlmzb. r5, r6, r7 *)
    checkDlmzb "7cc5389d"
      [ 0x8UL, 0x8UL, 0x2UL
        0x1UL, 0xe0000001UL, 0x5UL
        0x3UL, 0x20000003UL, 0x4UL
        0x4UL, 0x80000004UL, 0x5UL
        0x6UL, 0x40000006UL, 0x8UL
        0x7UL, 0x7UL, 0x8UL
        0x8UL, 0x20000008UL, 0x8UL
        0x1UL, 0xa0000001UL, 0x5UL
        0x8UL, 0xe0000008UL, 0x3UL
        0x1UL, 0xfff3ff81UL, 0x5UL ]

/// <summary>
/// Lifting tests of the instructions the embedded environment adds (Power ISA
/// 2.07B Book II and Book III-E). qemu-ppc -cpu e500mc (8.2.2) runs only some
/// of them and no test of these depends on a value it gave: where it runs one,
/// the test says what it saw; the rest are the manual's.
/// </summary>
[<TestClass>]
type EmbeddedLifterTests() =
  /// Whether a lifted statement is one of the marks that open and close an
  /// instruction, and so does nothing.
  let isMark = function
    | ISMark _ | IEMark _ -> true
    | _ -> false

  /// Asserts that a word lifts to nothing but the marks of the instruction, on
  /// every processor, and that over registers holding values and memory
  /// holding bytes it leaves all of them as they were.
  let checkNoTraceOn isas hex =
    for isa in isas do
      Assert.IsTrue(Array.forall isMark (lifted isa hex), $"{hex} {isa}")
      let given = [ R5, 5UL; R6, 0x20200078UL; R7, 8UL; XER, 0xe0000000UL ]
      let after, memory = exec isa hex given []
      for r, v in given do
        Assert.AreEqual(box v, box (after r), $"{hex} {r} {isa}")
      Assert.AreEqual(box 0, box memory.Count, $"{hex} memory {isa}")

  /// The same on every processor with the server reading of every encoding.
  let checkNoTrace hex = checkNoTraceOn everyProcessor hex

  /// The big-endian processors, whose byte order is the order of the manual's
  /// drawings.
  let bigEndian = everyProcessor |> List.filter (fun i -> i.Endian = Endian.Big)

  /// The doubleword forms of decorated storage are the 64-bit category's, so
  /// they run on the 64-bit processors only.
  let only64Bit =
    everyProcessor |> List.filter (fun i -> i.WordSize = WordSize.Bit64)

  /// Eight bytes of memory at the address the decorated accesses use, which no
  /// access reaches by adding rA (holding 0x11, a decoration) to it.
  let decorated =
    [| 0x81uy; 0x92uy; 0xa3uy; 0xb4uy; 0xc5uy; 0xd6uy; 0xe7uy; 0xf8uy |]

  /// The value a load of the first size bytes of memory reads on a processor
  /// of the byte order an ISA names.
  let readOf (isa: ISA) size =
    let bytes = Array.take size decorated
    let ordered = if isa.Endian = Endian.Big then bytes else Array.rev bytes
    ordered |> Array.fold (fun acc b -> (acc <<< 8) ||| uint64 b) 0UL

  /// Asserts what a decorated load of size bytes puts in rT (r5, or f5 where
  /// it is a floating-point register) on each processor given: the bytes at
  /// rB (r7) alone, zero-extended, whatever the decoration in rA (r6) is.
  let checkDecoratedLoad isas hex target size =
    for isa in isas do
      let given = [ target, 0xffffffffUL; R6, 0x11UL; R7, 0x2000UL ]
      let after, memory = exec isa hex given [ 0x2000UL, decorated ]
      let case = $"{hex} {isa}"
      Assert.AreEqual(box (readOf isa size), box (after target), case)
      Assert.AreEqual(box 8, box memory.Count, $"{hex} memory {isa}")

  /// Asserts what a decorated store of size bytes writes at rB (r7) on each
  /// processor given: the low size bytes of rS (r5, or f5), in the processor's
  /// byte order, and nothing else, whatever the decoration in rA (r6) is.
  let checkDecoratedStore isas hex source size =
    for isa in isas do
      let narrow = Expr.typeOf (var isa source) = 32<rt>
      let value = if narrow then 0x85868788UL else 0x8182838485868788UL
      let given = [ source, value; R6, 0x11UL; R7, 0x2000UL ]
      let _, memory = exec isa hex given []
      let bits = 8 * size
      let mask = if bits = 64 then UInt64.MaxValue else (1UL <<< bits) - 1UL
      let low = value &&& mask
      let wanted =
        [| for i in 0 .. size - 1 -> byte (low >>> (8 * (size - 1 - i))) |]
      let ordered = if isa.Endian = Endian.Big then wanted else Array.rev wanted
      let last = 0x2000UL + uint64 size - 1UL
      let written = [| for a in 0x2000UL .. last -> memory[a] |]
      let case = $"{hex} {isa}"
      let wantedBytes = box (List.ofArray ordered)
      Assert.AreEqual(wantedBytes, box (List.ofArray written), case)
      Assert.AreEqual(box size, box memory.Count, case)

  /// The side effects a word lifts to on every processor, one list each.
  let effectsOf hex =
    [ for isa in everyProcessor ->
        lifted isa hex
        |> Array.choose (function
          | SideEffect(Effect = effect) -> Some effect
          | _ -> None)
        |> List.ofArray ]

  /// Runs a lock query with CR0 holding every bit set and XER's SO as
  /// given, and asserts CR0 holds 0b00 || 0 || SO: the block is never locked.
  let checkQuery hex =
    for isa in everyProcessor do
      for xer, field in [ 0UL, 0UL; 0x80000000UL, 1UL; 0x60000000UL, 0UL ] do
        let given =
          [ CR0_0, 1UL; CR0_1, 1UL; CR0_2, 1UL; CR0_3, 1UL; XER, xer ]
        let after = run isa hex given
        let case = $"{hex} {xer:x} {isa}"
        Assert.AreEqual(box field, box (cr0 after), case)
        Assert.AreEqual(box xer, box (after XER), case)

  /// <summary>
  /// dcblc CT, rA, rB unlocks a block of a cache the model does not have
  /// locked, and so lifts to nothing. qemu-ppc -cpu e500mc (8.2.2) runs it and
  /// changes no register or memory.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] DCBLC leaves no trace``() =
    checkNoTrace "7c263b0c"

  /// <summary>
  /// dcblq. CT, rA, rB reports whether the block is locked in CR0: 0b00, the
  /// status (0, where a query cannot be answered, and no lock is ever set),
  /// and XER's SO. The manual's pseudocode; QEMU has no dcblq. on the e500mc.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] DCBLQ. reports a block that is not locked``() =
    checkQuery "7c263b4d"

  /// <summary>
  /// dcbtls CT, rA, rB is a hint to load and lock a block, which may fail to
  /// lock ("an unable-to-lock condition may occur"), and the model leaves no
  /// trace. qemu-ppc -cpu e500mc (8.2.2) runs it and changes no register or
  /// memory (it records the failure in L1CSR0, which nothing here models).
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] DCBTLS leaves no trace``() =
    checkNoTrace "7c46394c"

  /// <summary>
  /// dcbtstls CT, rA, rB, the same hint for a store. The manual's; QEMU has no
  /// dcbtstls on the e500mc.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] DCBTSTLS leaves no trace``() =
    checkNoTrace "7c46390c"

  /// <summary>
  /// icblc CT, rA, rB unlocks a block of an instruction cache the model does
  /// not have locked. The manual's; QEMU has no icblc on the e500mc.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] ICBLC leaves no trace``() =
    checkNoTrace "7c2639cc"

  /// <summary>
  /// icblq. CT, rA, rB reports a block of the instruction cache that is not
  /// locked in CR0, as dcblq. does. The manual's; QEMU has no icblq. on the
  /// e500mc.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] ICBLQ. reports a block that is not locked``() =
    checkQuery "7c26398d"

  /// <summary>
  /// icbtls CT, rA, rB is a hint to load a block into the instruction cache and
  /// lock it, which may fail to lock. The manual's; QEMU has no icbtls on the
  /// e500mc.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] ICBTLS leaves no trace``() =
    checkNoTrace "7c463bcc"

  /// <summary>
  /// mbar MO orders the storage accesses of the program, and nothing the model
  /// holds changes. qemu-ppc -cpu e500mc and -cpu 440epx (8.2.2) run it with MO
  /// 0, 1 and 31 and change no register.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] MBAR leaves no trace``() =
    for hex in [ "7c0006ac"; "7c2006ac"; "7fe006ac" ] do
      checkNoTraceOn embeddedProcessors hex

  /// <summary>
  /// dnh DUI, DUIS halts the thread where an implementation-dependent means
  /// has enabled it and otherwise raises an illegal instruction exception,
  /// which is all a user-level program can reach. qemu-ppc -cpu e500mc (8.2.2)
  /// raises SIGILL.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] DNH raises an illegal instruction exception``() =
    let expected = box [ B2R2.BinIR.SideEffect.UndefinedInstruction ]
    for effects in effectsOf "4c20118c" do
      Assert.AreEqual(expected, box effects)

  /// <summary>
  /// ehpriv OC generates an Embedded Hypervisor Privilege exception, "analogous
  /// to a guaranteed illegal instruction encoding", and a user-level program
  /// has no hypervisor to take it. qemu-ppc -cpu e500mc (8.2.2) raises SIGILL.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] EHPRIV raises an illegal instruction exception``() =
    let expected = box [ B2R2.BinIR.SideEffect.UndefinedInstruction ]
    for effects in effectsOf "7c002a1c" do
      Assert.AreEqual(expected, box effects)

  /// <summary>
  /// mfpmr rT, PMRN reads a performance monitor register. No event is ever
  /// counted and no performance monitor is modeled, so rT reads 0 whatever
  /// the register: a choice the architecture leaves open, which QEMU (it has
  /// no mfpmr in user mode) cannot confirm.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] MFPMR reads zero``() =
    for isa in everyProcessor do
      for hex in [ "7cb0029c"; "7cb0629c" ] do
        let after = run isa hex [ R5, 0x1234UL; R6, 7UL ]
        Assert.AreEqual(box 0UL, box (after R5), $"{hex} {isa}")
        Assert.AreEqual(box 7UL, box (after R6), $"{hex} {isa}")

  /// <summary>
  /// mtpmr PMRN, rS writes a performance monitor register that is not modeled,
  /// and nothing the model holds changes.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] MTPMR leaves no trace``() =
    for hex in [ "7cb0039c"; "7cb0639c" ] do
      checkNoTrace hex

  /// <summary>
  /// mfdcrux rT, rA reads the device control register rA names, the state of a
  /// device that is not modeled, so it is an instruction B2R2 does not lift.
  /// qemu-ppc -cpu 440epx (8.2.2) raises SIGILL.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] MFDCRUX is not lifted``() =
    let expected = box [ B2R2.BinIR.SideEffect.UnsupportedInstruction ]
    for effects in effectsOf "7ca60246" do
      Assert.AreEqual(expected, box effects)

  /// <summary>
  /// mtdcrux rA, rS writes a device control register, the same. qemu-ppc -cpu
  /// 440epx (8.2.2) raises SIGILL.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] MTDCRUX is not lifted``() =
    let expected = box [ B2R2.BinIR.SideEffect.UnsupportedInstruction ]
    for effects in effectsOf "7cc50346" do
      Assert.AreEqual(expected, box effects)

  /// <summary>
  /// xnop is a no-op that executes: it lifts to the marks of the instruction
  /// alone, where xori 0, 0, 0 would write r0. qemu-ppc -cpu e500mc (8.2.2)
  /// runs it and changes no register.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] XNOP leaves no trace``() =
    checkNoTrace "68000000"

  /// <summary>
  /// dcba rA, rB is a hint that the program will store into the block and does
  /// not care about the rest of it, and leaves no trace. qemu-ppc -cpu e500mc
  /// and -cpu 440epx (8.2.2) run it and change no register or memory.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] DCBA leaves no trace``() =
    checkNoTrace "7c063dec"

  /// <summary>
  /// mcrxr crD copies the SO, OV and CA bits of XER into the first three bits
  /// of CR field crD, the fourth being the bit XER holds above them, and
  /// clears them. The seeds keep that reserved bit clear: qemu-ppc -cpu 440epx
  /// and -cpu e500mc (8.2.2), which supply every expected value, leave it
  /// alone where the manual's pseudocode copies it and clears it too.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] MCRXR copies XER into a CR field``() =
    (* mcrxr cr3 *)
    for isa in everyProcessor do
      for xer, field, xerAfter in
        [ 0x0UL, 0x0UL, 0x0UL
          0x80000000UL, 0x8UL, 0x0UL
          0x40000000UL, 0x4UL, 0x0UL
          0x20000000UL, 0x2UL, 0x0UL
          0xe0000000UL, 0xeUL, 0x0UL
          0x60000000UL, 0x6UL, 0x0UL
          0xa0000000UL, 0xaUL, 0x0UL
          0xc0000000UL, 0xcUL, 0x0UL
          0xe003ffffUL, 0xeUL, 0x3ffffUL ] do
        for before in [ 0UL; 1UL ] do
          let given =
            [ CR3_0, before
              CR3_1, before
              CR3_2, before
              CR3_3, before
              XER, xer ]
          let after = run isa "7d800400" given
          let case = $"{xer:x} {before} {isa}"
          let nibble =
            (after CR3_0 <<< 3) ||| (after CR3_1 <<< 2) ||| (after CR3_2 <<< 1)
            ||| after CR3_3
          Assert.AreEqual(box field, box nibble, case)
          Assert.AreEqual(box xerAfter, box (after XER), case)

  /// <summary>
  /// eciwx rT, rA, rB sends a load word request for (rA|0) + (rB) to the
  /// device the EAR names and puts the word it returns into the low half of
  /// rT, the high half 0. The word comes back as one the processor reads from
  /// memory, so on a big-endian processor it is the four bytes in order; the
  /// byte order a device returns it in is the device's own, which the manual
  /// leaves open, so only the big-endian processors are asserted. QEMU 8.2.2
  /// has no eciwx for the 440 or the e500mc (SIGILL).
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] ECIWX loads a word``() =
    (* eciwx r5, r6, r7 *)
    for isa in bigEndian do
      let memory = [ 0x2000UL, [| 0x12uy; 0x34uy; 0x56uy; 0x78uy |] ]
      let given = [ R5, UInt64.MaxValue; R6, 0x1ff8UL; R7, 8UL ]
      let after, _ = exec isa "7ca63a6c" given memory
      Assert.AreEqual(box 0x12345678UL, box (after R5), $"{isa}")

  /// <summary>
  /// ecowx rS, rA, rB sends the low word of rS and a store word request for
  /// (rA|0) + (rB) to the device the EAR names. The device is memory here, and
  /// a big-endian processor stores the four bytes in order. QEMU 8.2.2 has no
  /// ecowx for the 440 or the e500mc (SIGILL).
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] ECOWX stores a word``() =
    (* ecowx r5, r6, r7 *)
    let expected = box [ 0x12uy; 0x34uy; 0x56uy; 0x78uy ]
    for isa in bigEndian do
      let given = [ R5, 0xdeadbeef12345678UL; R6, 0x1ff8UL; R7, 8UL ]
      let _, memory = exec isa "7ca63b6c" given []
      let bytes = [ for a in 0x2000UL .. 0x2003UL -> memory[a] ]
      Assert.AreEqual(expected, box bytes, $"{isa}")

  /// <summary>
  /// lbdx rT, rA, rB loads the byte at the address rB holds, alone,
  /// zero-extended into rT, using the decoration rA holds; the decoration is a
  /// request to the storage controller, which the model has none of, so the
  /// access is the plain one. The manual's; QEMU 8.2.2 has no decorated storage
  /// (SIGILL on the e500mc).
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] LBDX loads a byte``() =
    checkDecoratedLoad everyProcessor "7ca63c06" R5 1

  /// <summary>
  /// lhdx rT, rA, rB loads the halfword at the address rB holds, zero-extended.
  /// The manual's.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] LHDX loads a halfword``() =
    checkDecoratedLoad everyProcessor "7ca63c46" R5 2

  /// <summary>
  /// lwdx rT, rA, rB loads the word at the address rB holds, zero-extended. The
  /// manual's.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] LWDX loads a word``() =
    checkDecoratedLoad everyProcessor "7ca63c86" R5 4

  /// <summary>
  /// lddx rT, rA, rB loads the doubleword at the address rB holds. The
  /// manual's.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] LDDX loads a doubleword``() =
    checkDecoratedLoad only64Bit "7ca63cc6" R5 8

  /// <summary>
  /// lfddx frT, rA, rB loads the doubleword at the address rB holds into a
  /// floating-point register, bit for bit. The manual's.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] LFDDX loads a floating doubleword``() =
    checkDecoratedLoad everyProcessor "7ca63e46" F5 8

  /// <summary>
  /// stbdx rS, rA, rB stores the low byte of rS at the address rB holds,
  /// alone. The manual's.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] STBDX stores a byte``() =
    checkDecoratedStore everyProcessor "7ca63d06" R5 1

  /// <summary>
  /// sthdx rS, rA, rB stores the low halfword of rS. The manual's.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] STHDX stores a halfword``() =
    checkDecoratedStore everyProcessor "7ca63d46" R5 2

  /// <summary>
  /// stwdx rS, rA, rB stores the low word of rS. The manual's.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] STWDX stores a word``() =
    checkDecoratedStore everyProcessor "7ca63d86" R5 4

  /// <summary>
  /// stddx rS, rA, rB stores rS. The manual's.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] STDDX stores a doubleword``() =
    checkDecoratedStore only64Bit "7ca63dc6" R5 8

  /// <summary>
  /// stfddx frS, rA, rB stores the floating-point register frS, bit for bit.
  /// The manual's.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] STFDDX stores a floating doubleword``() =
    checkDecoratedStore everyProcessor "7ca63f46" F5 8

  /// <summary>
  /// dsn rA, rB sends the decoration rA holds to the address rB holds, to the
  /// storage controller, which the model has none of: nothing the model holds
  /// changes. The manual's.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] DSN leaves no trace``() =
    checkNoTrace "7c063bc6"

/// <summary>
/// Lifting tests of the Transactional Memory instructions (Power ISA 2.07B
/// Book II chapter 5). B2R2 models a processor that fails every transaction,
/// as qemu-ppc64 -cpu power8 and power9 (8.2.2) do; the values asserted are
/// the ones the architecture fixes for that machine, and QEMU's wherever it
/// agrees with them.
/// </summary>
[<TestClass>]
type TransactionLifterTests() =
  /// The registers that nothing but tbegin. changes, given values no
  /// instruction here may disturb, with CR0 set and XER[SO] too, so that a CR0
  /// that is not written, or that copies SO, shows.
  let state =
    [ R5, 7UL
      R6, 1UL
      R7, 2UL
      XER, 0x80000000UL
      CR0_0, 1UL
      CR0_1, 1UL
      CR0_2, 1UL
      CR0_3, 1UL
      TEXASR, 0x1234UL
      TFHAR, 0x5678UL
      TFIAR, 0x9abcUL ]

  /// Asserts that a word leaves the state above as it was and clears CR0, on
  /// every processor. The Non-transactional state, which is the only one this
  /// machine has, gives CR0 the value 0 || MSR[TS] || 0.
  let checkClearsCR0 hex =
    for isa in everyProcessor do
      let after = run isa hex state
      let isCR0 r = r = CR0_0 || r = CR0_1 || r = CR0_2 || r = CR0_3
      for r, v in state |> List.filter (fun (r, _) -> not (isCR0 r)) do
        Assert.AreEqual(box v, box (after r), $"{hex} {r} {isa}")
      Assert.AreEqual(box 0UL, box (cr0 after), $"{hex} CR0 {isa}")

  /// What tbegin. leaves, at an address: the cause in TEXASR, the failure
  /// handler in TFHAR (the next instruction), the failing instruction in
  /// TFIAR, and CR0 set to 0b1010; the registers it does not name are as they
  /// were.
  let checkBegin hex texasr =
    for isa in everyProcessor do
      let address = 0x20100000UL
      let after = runAt isa address hex state
      let case = $"{hex} {isa}"
      Assert.AreEqual(box texasr, box (after TEXASR), case)
      Assert.AreEqual(box (address + 4UL), box (after TFHAR), case)
      Assert.AreEqual(box (address ||| 3UL), box (after TFIAR), case)
      Assert.AreEqual(box 0b1010UL, box (cr0 after), case)
      Assert.AreEqual(box 7UL, box (after R5), case)
      Assert.AreEqual(box 0x80000000UL, box (after XER), case)

  /// A value of a 64-bit register as a processor holds it: the whole of it on
  /// a 64-bit processor, its low word on a 32-bit one.
  let wideOr (isa: ISA) (wide: uint64) =
    if isa.WordSize = WordSize.Bit32 then wide &&& 0xffffffffUL else wide

  /// Asserts what a move from a transactional memory register puts in r5 on
  /// every processor, TEXASR holding 0x9abcdef0fedcba98 and TFHAR and TFIAR
  /// 0x123456789abcdef0, and that it changes nothing else.
  let checkMoveFrom hex expected =
    for isa in everyProcessor do
      let given =
        [ TEXASR, 0x9abcdef0fedcba98UL
          TFHAR, 0x123456789abcdef0UL
          TFIAR, 0x123456789abcdef0UL
          R6, 6UL ]
      let after = run isa hex given
      let case = $"{hex} {isa}"
      Assert.AreEqual(box (wideOr isa expected), box (after R5), case)
      Assert.AreEqual(box 6UL, box (after R6), case)
      Assert.AreEqual(box 0x9abcdef0fedcba98UL, box (after TEXASR), case)

  /// Asserts what a move to a transactional memory register leaves in it on
  /// every processor, r5 holding 0x123456789abcdef0 (its low word, on a 32-bit
  /// processor) and the registers the move does not name as given.
  let checkMoveTo hex register (expected: ISA -> uint64) =
    for isa in everyProcessor do
      let given =
        [ R5, wideOr isa 0x123456789abcdef0UL
          TEXASR, 0xfedcba98UL
          TFHAR, 0x1UL
          TFIAR, 0x2UL ]
      let after = run isa hex given
      let case = $"{hex} {isa}"
      Assert.AreEqual(box (expected isa), box (after register), case)
      for r, v in given |> List.filter (fun (r, _) -> r <> register) do
        Assert.AreEqual(box v, box (after r), $"{case} {r}")

  /// <summary>
  /// tbegin. 0 begins a transaction that fails as it begins, as a processor
  /// that fails every one does: TEXASR holds the transaction level 1 and the
  /// failure persistent, nesting overflow, privilege (HV and PR), failure
  /// summary and exact bits, TFHAR the address of the next instruction, TFIAR
  /// the address of the tbegin. with the privilege in its low bits, and CR0
  /// 0b101 || 0 (Book II 5.3.3, "TMHandleFailure"); control falls through to
  /// TFHAR. QEMU (8.2.2) gives these values where the tbegin. starts a
  /// translation block, as it does here, and differs on the rest
  /// (deviations/ppc64/tm_qemu.c): it leaves the transaction level 0 and sets
  /// CR0 to 0b1011.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] TBEGIN. fails the transaction at once``() =
    (* tbegin. 0 *)
    checkBegin "7c00051d" 0x0140_0000_3c00_0001UL

  /// <summary>
  /// tbegin. 1 begins a rollback-only transaction, which also sets TEXASR bit
  /// 38. QEMU (8.2.2) leaves the bit clear for both forms.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] TBEGIN. 1 sets the rollback-only bit``() =
    (* tbegin. 1 *)
    checkBegin "7c20051d" 0x0140_0000_3e00_0001UL

  /// <summary>
  /// tend. A ends the transaction there is none of: CR0 is set to 0 || MSR[TS]
  /// || 0, which is 0, whatever XER[SO] holds, and nothing else changes. The
  /// values are QEMU's.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] TEND. leaves CR0 clear``() =
    checkClearsCR0 "7c00055d"
    checkClearsCR0 "7e00055d"

  /// <summary>
  /// tabort. rA aborts nothing outside a transaction: CR0 is set to 0 and rA
  /// is not read. QEMU's values.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] TABORT. leaves CR0 clear``() =
    checkClearsCR0 "7c05071d"

  /// <summary>
  /// tabortdc. TO, rA, rB compares and aborts only in a transaction: CR0 is
  /// set to 0 whether or not the comparison holds (rA 1, rB 2, TO 5). QEMU's
  /// values.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] TABORTDC. leaves CR0 clear``() =
    checkClearsCR0 "7ca63e5d"

  /// <summary>
  /// tabortdci. TO, rA, SI, the same against an immediate. QEMU's values.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] TABORTDCI. leaves CR0 clear``() =
    checkClearsCR0 "7ca6cedd"

  /// <summary>
  /// tabortwc. TO, rA, rB, the same on the low words. QEMU's values.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] TABORTWC. leaves CR0 clear``() =
    checkClearsCR0 "7ca63e1d"

  /// <summary>
  /// tabortwci. TO, rA, SI, the same against an immediate. QEMU's values.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] TABORTWCI. leaves CR0 clear``() =
    checkClearsCR0 "7ca6ce9d"

  /// <summary>
  /// tsr. L suspends or resumes a transaction there is none of: CR0 is set to
  /// 0 and nothing else changes. QEMU's values.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] TSR. leaves CR0 clear``() =
    checkClearsCR0 "7c0005dd"
    checkClearsCR0 "7c2005dd"

  /// <summary>
  /// tcheck BF sets the field BF to TDOOMED || MSR[TS] || 0: the transaction
  /// state is Non-transactional, and the machine that fails every transaction
  /// has TDOOMED set. The other fields are untouched. QEMU's value (0b1000).
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] TCHECK sets a field to doomed``() =
    (* tcheck cr2 *)
    for isa in everyProcessor do
      let given =
        [ CR2_0, 0UL
          CR2_1, 1UL
          CR2_2, 1UL
          CR2_3, 1UL
          CR3_0, 1UL
          CR1_3, 1UL ]
      let after = run isa "7d00059c" given
      let field =
        (after CR2_0 <<< 3) ||| (after CR2_1 <<< 2) ||| (after CR2_2 <<< 1)
        ||| after CR2_3
      Assert.AreEqual(box 0b1000UL, box field, $"{isa}")
      Assert.AreEqual(box 1UL, box (after CR3_0), $"{isa}")
      Assert.AreEqual(box 1UL, box (after CR1_3), $"{isa}")

  /// <summary>
  /// mftfhar rT reads TFHAR, the address a failed transaction continues at.
  /// The manual's extended mnemonic for mfspr rT, 128; QEMU's value
  /// (qemu-ppc64 -cpu power9, 8.2.2, reads back what was written).
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] MFTFHAR reads TFHAR``() =
    checkMoveFrom "7ca022a6" 0x123456789abcdef0UL

  /// <summary>
  /// mftfiar rT reads TFIAR, the address of the instruction that failed a
  /// transaction (mfspr rT, 129). QEMU's value.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] MFTFIAR reads TFIAR``() =
    checkMoveFrom "7ca122a6" 0x123456789abcdef0UL

  /// <summary>
  /// mftexasr rT reads TEXASR, the transaction status (mfspr rT, 130). QEMU's
  /// value.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] MFTEXASR reads TEXASR``() =
    checkMoveFrom "7ca222a6" 0x9abcdef0fedcba98UL

  /// <summary>
  /// mftexasru rT reads TEXASRU, the upper word of TEXASR, into the low word
  /// of rT (mfspr rT, 131). QEMU's value.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] MFTEXASRU reads the upper word of TEXASR``() =
    checkMoveFrom "7ca322a6" 0x9abcdef0UL

  /// <summary>
  /// mttfhar rS writes TFHAR with rS (mtspr 128, rS). The manual's extended
  /// mnemonic; QEMU keeps all 64 bits as written.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] MTTFHAR writes TFHAR``() =
    checkMoveTo "7ca023a6" TFHAR (fun isa -> wideOr isa 0x123456789abcdef0UL)

  /// <summary>
  /// mttfiar rS writes TFIAR with rS (mtspr 129, rS). QEMU keeps all 64 bits.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] MTTFIAR writes TFIAR``() =
    checkMoveTo "7ca123a6" TFIAR (fun isa -> wideOr isa 0x123456789abcdef0UL)

  /// <summary>
  /// mttexasr rS writes TEXASR with rS (mtspr 130, rS). QEMU keeps all 64
  /// bits.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] MTTEXASR writes TEXASR``() =
    checkMoveTo "7ca223a6" TEXASR (fun isa -> wideOr isa 0x123456789abcdef0UL)

  /// <summary>
  /// mttexasru rS writes the upper word of TEXASR with the low word of rS
  /// (mtspr 131, rS) and leaves the lower word. QEMU's value.
  /// </summary>
  [<TestMethod>]
  member _.``[PPC] MTTEXASRU writes the upper word of TEXASR``() =
    checkMoveTo "7ca323a6" TEXASR (fun _ -> 0x9abcdef0fedcba98UL)

(* Lane S: the Signal Processing Engine. *)

/// <summary>
/// Lane S's lifting tests: the instructions of the Signal Processing Engine,
/// run on the e500 (a 32-bit processor whose general registers the engine
/// widens to 64 bits, the high word in R0H-R31H) and on a 64-bit processor
/// with the engine. Every expected value is what qemu-ppc -cpu e500v2 (QEMU
/// 8.2.2) left in the register, run through optest-powerpc/oracle over the
/// same values, unless a test says that the manual and QEMU part, in which
/// case it is the manual's (deviations/ppc/spe_*.c) -- or that QEMU does not
/// run the instruction (it raises SIGILL for 90 of the 248), in which case it
/// is spe/model.py's, a second reading of the manual's pseudocode written
/// apart from B2R2 and checked against QEMU wherever QEMU runs something.
/// <para>
/// A table of cases is hexadecimal numbers, whatever the line breaks between
/// them: a case of arith is RA, RB, ACC and SPEFSCR as they were given, then
/// RT, ACC and SPEFSCR as the word left them; a case of compare is RA, RB and
/// SPEFSCR, then the CR field the word wrote.
/// </para>
/// </summary>
[<TestClass>]
type SignalProcessingLifterTests() =
  /// The categories of a processor with the engine.
  let engine = int Category.SignalProcessing

  /// The e500, a 32-bit processor whose general registers the engine widens
  /// to 64 bits: the low word is R0-R31 and the high word R0H-R31H.
  let engine32 = ISA(Architecture.PPC, Endian.Big, WordSize.Bit32, engine)

  /// A 64-bit processor with the engine, whose registers are 64 bits wide to
  /// begin with.
  let engine64 = ISA(Architecture.PPC, Endian.Big, WordSize.Bit64, engine)

  /// Both of them.
  let engines = [ engine32; engine64 ]

  /// The same two processors running little-endian, which no reference here
  /// runs: their cases are the manual's, read by spe/model.py.
  let engine32le = ISA(Architecture.PPC, Endian.Little, WordSize.Bit32, engine)

  let engine64le = ISA(Architecture.PPC, Endian.Little, WordSize.Bit64, engine)

  let littleEngines = [ engine32le; engine64le ]

  /// What R5 holds before a word that writes it runs, so that a result equal
  /// to a seed still shows.
  let before = 0x0bad0bad0bad0badUL

  /// The numbers of a table of cases, a case of the given width at a time.
  let rows (width: int) (table: string) =
    table.Split([| ' '; char 10 |], StringSplitOptions.RemoveEmptyEntries)
    |> Array.map (fun token -> Convert.ToUInt64(token, 16))
    |> Array.chunkBySize width

  /// The statements one word lifts to on the processor an ISA names. The hex
  /// is the word as the Power ISA draws it, most significant byte first, and
  /// it is laid in memory in the byte order of the ISA.
  let lifted (isa: ISA) (hex: string) =
    let word = ByteArray.ofHexString hex
    let bytes = if isa.Endian = Endian.Big then word else Array.rev word
    let reader = BinReader.Init isa.Endian
    let parser = Parser(isa, reader) :> IInstructionParsable
    let regs = RegisterFactory isa :> IRegisterFactory
    let builder = ILowUIRBuilder.Default(isa, regs, LowUIRStream())
    (parser.Parse(bytes, 0UL)).Translate builder

  /// The variable of a register on the processor an ISA names.
  let var (isa: ISA) r =
    (RegisterFactory isa :> IRegisterFactory).GetRegVar(Register.toRegID r)

  /// The register that holds the high word of a general register.
  let highOf (r: Register) = enum<Register> (int r + int R0H)

  /// Whether a register is one of the 64-bit general registers.
  let isGeneral (r: Register) = r >= R0 && r <= R31

  /// The registers given values as the processor of an ISA holds them: a
  /// general register is given as its 64 bits, which a 32-bit processor keeps
  /// in two.
  let inputsOf (isa: ISA) given =
    given
    |> List.collect (fun (r, v: uint64) ->
      if isGeneral r && isa.WordSize = WordSize.Bit32 then
        [ highOf r, v >>> 32; r, v &&& 0xffffffffUL ]
      else
        [ r, v ])
    |> List.map (fun (r, v) ->
      let x = var isa r
      x, BitVector(v, Expr.typeOf x))

  /// What a register holds after a run, a general register as its 64 bits.
  let readBack (isa: ISA) (read: Expr -> BitVector) (r: Register) =
    let value x = (read (var isa x)).ToUInt64()
    if isGeneral r && isa.WordSize = WordSize.Bit32 then
      (value (highOf r) <<< 32) ||| value r
    else
      value r

  /// Where the cases of an access put it: the middle of the window the oracle
  /// ran them in.
  let target = 0x20200080UL

  /// The sixteen bytes at target, from the two doublewords a case gives them
  /// as, in address order.
  let bytesOf (m0: uint64) (m1: uint64) =
    let bigEndian (v: uint64) = Array.rev (BitConverter.GetBytes v)
    Array.append (bigEndian m0) (bigEndian m1)

  /// Runs a word on each processor of a list over the registers and the
  /// memory given, and asserts that every register wanted holds its value
  /// afterwards and, for a store, that the bytes at target are the ones it
  /// left.
  let checkOn isas (hex: string) (label: string) given memory wanted stored =
    for isa in isas do
      let outcome = IRRunner.exec (lifted isa hex) (inputsOf isa given) memory
      for r, v in wanted do
        let actual = readBack isa outcome.Read r
        Assert.AreEqual(box v, box actual, $"{hex} {label} {r} {isa.WordSize}")
      stored
      |> Array.iteri (fun i (b: byte) ->
        let actual = outcome.Memory[target + uint64 i]
        let message = $"{hex} {label} byte {i} {isa.WordSize}"
        Assert.AreEqual(box b, box actual, message))

  /// The same on the big-endian processors.
  let checkWith hex label given memory wanted stored =
    checkOn engines hex label given memory wanted stored

  /// The same where the word touches no memory.
  let check hex label given wanted = checkWith hex label given [] wanted [||]

  /// The cases of a word that reads RA (r6) and RB (r7), the accumulator and
  /// SPEFSCR and writes RT (r5), the accumulator and SPEFSCR.
  let arith hex table =
    for c in rows 7 table do
      let label = $"{c[0]:x} {c[1]:x} {c[2]:x} {c[3]:x}"
      let given = [ R5, before; R6, c[0]; R7, c[1]; ACC, c[2]; SPEFSCR, c[3] ]
      let wanted = [ R5, c[4]; ACC, c[5]; SPEFSCR, c[6] ]
      check hex label given wanted

  /// The four bits of a CR field as the Power ISA draws them, LT first, in
  /// the order of the one-bit registers B2R2 keeps them in.
  let fieldBits (first: Register) (field: uint64) =
    [ for i in 0 .. 3 ->
        enum<Register> (int first + i), (field >>> (3 - i)) &&& 1UL ]

  /// The cases of a load word on the processors of a list: RA (r6), RB (r7)
  /// and the sixteen bytes at the address it forms, then RT.
  let loadOn isas hex table =
    for c in rows 5 table do
      let label = $"{c[0]:x} {c[1]:x} {c[2]:x} {c[3]:x}"
      let given = [ R5, before; R6, c[0]; R7, c[1] ]
      let memory = [ target, bytesOf c[2] c[3] ]
      checkOn isas hex label given memory [ R5, c[4] ] [||]

  let load hex table = loadOn engines hex table

  let loadLE hex table = loadOn littleEngines hex table

  /// The cases of a store word on the processors of a list: RS (r5), RA
  /// (r6), RB (r7) and the sixteen bytes at the address it forms, then the
  /// bytes it left there.
  let storeOn isas hex table =
    for c in rows 7 table do
      let label = $"{c[0]:x} {c[1]:x} {c[2]:x} {c[3]:x} {c[4]:x}"
      let given = [ R5, c[0]; R6, c[1]; R7, c[2] ]
      let memory = [ target, bytesOf c[3] c[4] ]
      checkOn isas hex label given memory [ R5, c[0] ] (bytesOf c[5] c[6])

  let store hex table = storeOn engines hex table

  let storeLE hex table = storeOn littleEngines hex table

  /// The one-bit registers of a CR field, LT first.
  let crBits (field: int) = enum<Register> (int CR0_0 + 4 * field)

  /// The cases of a compare word that writes CR field bf from RA (r6) and RB
  /// (r7).
  let compare hex bf table =
    for c in rows 4 table do
      let label = $"{c[0]:x} {c[1]:x} {c[2]:x}"
      let given = [ R6, c[0]; R7, c[1]; SPEFSCR, c[2] ]
      check hex label given (fieldBits (crBits bf) c[3])

  /// The cases of a word that chooses between RA (r6) and RB (r7) by CR field
  /// bfa: RA, RB and the field, then RT.
  let select hex bfa table =
    for c in rows 4 table do
      let label = $"{c[0]:x} {c[1]:x} {c[2]:x}"
      let given = [ R5, before; R6, c[0]; R7, c[1] ]
      check hex label (given @ fieldBits (crBits bfa) c[2]) [ R5, c[3] ]
  /// Floating-point cases on both widths and byte orders. Scalar singles
  /// preserve the high word and every instruction preserves ACC.
  let fpArith hex table =
    for c in rows 7 table do
      let given =
        [ R5, before; R6, c[0]; R7, c[1]; ACC, c[2]; SPEFSCR, c[3] ]
      let wanted = [ R5, c[4]; ACC, c[5]; SPEFSCR, c[6] ]
      let targets = engines @ littleEngines
      checkOn targets hex "floating point" given [] wanted [||]

  /// All condition bits, to prove a comparison preserves every other field.
  let wholeCR value =
    [ for field in 0 .. 7 do
        let bits = (value >>> (28 - 4 * field)) &&& 15UL
        yield! fieldBits (crBits field) bits ]

  /// Comparison cases include the complete old and new CR and SPEFSCR.
  let fpCompare hex table =
    for c in rows 6 table do
      let given =
        [ R5, before; R6, c[0]; R7, c[1]; SPEFSCR, c[2] ] @ wholeCR c[3]
      let wanted = [ R5, before; SPEFSCR, c[5] ] @ wholeCR c[4]
      let targets = engines @ littleEngines
      checkOn targets hex "floating comparison" given [] wanted [||]

  [<TestMethod>]
  member _.``[PPC] EVADDIW (Add Immediate Word)``() =
    (* evaddiw r5, r7, 12 *)
    arith "10ac3a02" """
      0 7fffffff7fffffff 100000002 0
      8000000b8000000b 100000002 0
      0 3000555555555 1234567889abcdef 80008000
      3001155555561 1234567889abcdef 80008000
      0 80007fffaaaaaaaa ffffffff 40004000
      8000800baaaaaab6 ffffffff 40004000
      0 1f7fff7fff 4000000040000000 1
      2b7fff800b 4000000040000000 1
      0 7fffffff7fffffff 8000000080000000 2
      8000000b8000000b 8000000080000000 2
      0 ffff00010000ffff ffffffffffffffff 3
      ffff000d0001000b ffffffffffffffff 3
      0 55555555aaaaaaaa 80000000ffffffff f01
      55555561aaaaaab6 80000000ffffffff f01
      0 3000540000000 c0000000c0000000 80008f00
      300114000000c c0000000c0000000 80008f00
      0 12345678deadbeef 80000000ffffffff 0
      12345684deadbefb 80000000ffffffff 0
      0 400040007fffffff 100000002 80008000
      4000400c8000000b 100000002 80008000
      """
    arith "10a03a02" """
      0 8000ffffaaaaaaaa 7fffffff7fffffff 0
      8000ffffaaaaaaaa 7fffffff7fffffff 0
      0 80007fffffff 8000000080000000 80008000
      80007fffffff 8000000080000000 80008000
      0 7fff 100000002 40004000
      7fff 100000002 40004000
      """
    arith "10bf3a02" """
      0 1000100000000 ffffffff00000000 0
      100200000001f ffffffff00000000 0
      0 80007fff00000020 80000000ffffffff 80008000
      8000801e0000003f 80000000ffffffff 80008000
      0 ffff00010000001f ffffffffffffffff 40004000
      ffff00200000003e ffffffffffffffff 40004000
      """

  [<TestMethod>]
  member _.``[PPC] EVADDW (Add Word)``() =
    (* evaddw r5, r6, r7 *)
    arith "10a63a00" """
      7fffffff40000000 400040008000ffff ffffffffffffffff 0
      c0003fffc000ffff ffffffffffffffff 0
      7fffffff8000 55555555ffff0001 ffffffffffffffff 80008000
      5555d554fffe8001 ffffffffffffffff 80008000
      800080008000 80007fff0000ffff 0 40004000
      8000ffff80017fff 0 40004000
      1234567800000020 30005aaaaaaaa 80000000ffffffff 1
      1237567daaaaaaca 80000000ffffffff 1
      deadbeef40000000 ffff000100000020 0 2
      deacbef040000020 0 2
      1f0000003f 1ffffffff ffffffff 3
      200000003e ffffffff 3
      fffd00050000ffff 1fffd0005 c0000000c0000000 f01
      fffd0006fffe0004 c0000000c0000000 f01
      ffff40000000 10001 80000000ffffffff 80008f00
      ffff40010001 80000000ffffffff 80008f00
      ffff0000ffff 3000540004000 100000002 0
      4000440013fff 100000002 0
      7fff7fff55555555 1deadbeef 8000000080000000 80008000
      7fff800034031444 8000000080000000 80008000
      """

  [<TestMethod>]
  member _.``[PPC] EVAND (AND)``() =
    (* evand r5, r6, r7 *)
    arith "10a63a11" """
      7fff800012345678 10000003f 1234567889abcdef 0
      38 1234567889abcdef 0
      80008000 12345678 ffffffffffffffff 80008000
      0 ffffffffffffffff 80008000
      fffd0005aaaaaaaa 2040004000 100000002 40004000
      0 100000002 40004000
      80008000 ffff8000 8000000080000000 1
      80008000 8000000080000000 1
      9abcdef00000ffff 7fffaaaaaaaa 7fffffff00000001 2
      5ef00000aaaa 7fffffff00000001 2
      2055555555 1fffffffff 7fffffff00000001 3
      55555555 7fffffff00000001 3
      3f9abcdef0 8000ffff00000001 100000002 f01
      3f00000000 100000002 f01
      7fff7fff00007fff 800000000000ffff c0000000c0000000 80008f00
      7fff c0000000c0000000 80008f00
      7fff7fff7fff8000 1f80007fff 100000002 0
      1f00000000 100000002 0
      1fffffffff 1f40004000 ffffffff00000000 80008000
      1f40004000 ffffffff00000000 80008000
      """

  [<TestMethod>]
  member _.``[PPC] EVANDC (AND with Complement)``() =
    (* evandc r5, r6, r7 *)
    arith "10a63a12" """
