    let w4 = 0x2468acf13579bcfUL
    let w5 = 0xffffffffffffffffUL
    let w6 = 0xfffffffffffffffdUL
    for isa, r3, r4, r3' in
      [ (vle32, 0x12345678UL, 0x9abcdef0UL, 0x77777788UL)
