        (vle32, 0xffffffffUL, 0UL)
        (vle32, 0xffff8001UL, 0x7ffeUL)
        (vle64, 0x12345678UL, w1)
        (vle64, 0x80UL, w2)
        (vle64, 0xffUL, w3)
        (vle64, 0x7fUL, w4)
